INSERT INTO agent_runs VALUES('agent_run_dbe8c1c2-88d5-47b0-902a-9839dde48e09','orchestrator','orchestrator_plan_v1','OrchestratorPlanV1','{"teacherId": "user_teacher_demo", "studentId": "student_life_bus", "caseId": "case_life_bus", "requestedGoal": "\ud559\uad50 \uc77c\uc815\uc774 \ubc14\ub00c\uc5b4 \uccb4\uc721\uad00 \ub300\uc2e0 \uc0c1\ub2f4\uc2e4\ub85c \uc774\ub3d9\ud574\uc57c \ud558\ub294 \uc0c1\ud669\uc5d0\uc11c, \uc548\ub0b4 \ub2e8\uc11c\ub97c \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \ub3c4\uc6c0\uc744 \uc9e7\uace0 \ubd84\uba85\ud558\uac8c \uc694\uccad\ud558\ub294 \uc5f0\uc2b5", "contentType": "life_support", "caseFile": {"profile": {"id": "student_life_bus", "organizationId": "org_yeongju_center", "externalKey": "demo_student_life_bus", "displayName": "\ubc15\uc218\ubbfc", "grade": "elementary_6", "schoolCode": "8811067", "studentType": "life_support", "primaryNeed": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c \ud655\uc778\uacfc \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \uc5f0\uc2b5\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "life_support", "gradeNumber": "6", "className": "1", "interests": ["\ub3d9\ub124 \uc9c0\ub3c4", "\uc5ed\ud560\uadf9"], "readingLoad": "very_low", "choiceCountLimit": 2, "dashboard": {"attendanceRate": 91, "gradeLabel": "\ucd086", "studentTypeLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "trackLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "statusLabel": "\ud559\uc2b5", "attendanceLabel": "91%", "summaryLine": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0 \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \ub9d0\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\uc77c\uc0c1\uc0dd\ud65c \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5", "primaryNeedDetail": "\ub0af\uc120 \uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \ub2e8\uc11c\ub97c \ud655\uc778\ud558\uace0 \