b77c \ubc14\ub010 \uc7a5\uc18c\ub97c \uc54c\ub824 \uc8fc\ub294 \uc2e4\uc81c \uc0dd\ud65c \ub2e8\uc11c\ub97c \ucc3e\ub3c4\ub85d \uad6c\uc131\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "3\ub2e8\uacc4 \uc21c\uc11c\uac00 \ub108\ubb34 \uae38\uc9c0 \uc54a\uac8c \uc548\ub0b4 \ud655\uc778, \ub3c4\uc6c0 \uc694\uccad, \uc0c1\ub2f4\uc2e4 \uc774\ub3d9 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ub9d0\ud558\uae30 \uc5f0\uc2b5 \ubb38\uc7a5\uc740 \u201c\uc0c1\ub2f4\uc2e4 \uc5b4\ub514\ub85c \uac00\uc694?\u201d\ucc98\ub7fc \uc9e7\uace0 \ubd84\uba85\ud55c \ud45c\ud604\uc73c\ub85c \uc81c\uacf5\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ucd086 \ud559\uc0dd\uc5d0\uac8c \uc5b4\uc6b8\ub9ac\ub294 \ud559\uad50 \uc0dd\ud65c \uc7a5\uba74\uc73c\ub85c \uc720\uc9c0\ub418\uace0, \uc9c0\ub098\uce58\uac8c \uc720\uc544\uc801\uc778 \uc18c\ud488\uc774\ub098 \ud45c\ud604\uc774 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc774\ubbf8\uc9c0 \uc548\uc5d0\ub294 \ubb38\uc81c \ubb38\uc7a5, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694."], "safetyNotes": ["\ud559\uc0dd\uc758 \uac1c\uc778\uc815\ubcf4\ub098 \uc2e4\uc81c \uc0c1\ub2f4 \ub0b4\uc6a9\uc740 \ubb3b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\uae38\uc744 \uc783\uc5c8\ub2e4\ub294 \ubd88\uc548\uc744 \ud0a4\uc6b0\ub294 \ud45c\ud604 \ub300\uc2e0 \ud655\uc778\ud558\uace0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4\ub294 \uc548\uc815\uc801\uc778 \ud45c\ud604\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.", "\ud559\uad50 \uacf5\uac1c \uc815\ubcf4\ub294 \ubc30\uacbd \ub9e5\ub77d\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uace0, \ud559\uc0dd \uac1c\uc778 \ub2a5\ub825 \ud310\ub2e8\uc5d0\ub294 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\uc0c1\ub2f4\uc2e4 \uc7a5\uba74\uc740 \uc0c1\ub2f4 \ub0b4\uc6a9\uc774 \uc544\ub2c8\ub77c \uc7a5\uc18c \uc774\ub3d9\uacfc \ub3c4\uc6c0 \uc694\uccad \uc5f0\uc2b5\uc73c\ub85c\ub9cc \ub2e4\ub8f9\ub2c8\ub2e4."]}','gpt-5.5','succeeded','{"input_tokens": 16780, "input_tokens_details": {"cached_tokens": 0}, "output_tokens": 2329, "output_tokens_details": {"reasoning_tokens": 516}, "total_tokens": 19109}',NULL,NULL,0,'2026-05-04T08:16:14.226157+00:00','2026-05-04T08:16:46.025971+00:00');
INSERT INTO agent_runs VALUES('agent_run_78b00f55-e0d7-4ec2-baa6-59d4d0bab63c','content','mission_content_package_v1','MissionContentPackageV1','{"teacherId": "user_teacher_demo", "studentId": "student_life_bus", "caseId": "case_life_bus", "orchestratorRunId": "agent_run_dbe8c1c2-88d5-47b0-902a-9839dde48e09", "orchestratorPlan": {"planVersion": "orchestrator_plan_v1", "studentId": "student_life_bus", "caseId": "case_life_bus", "contentType": "life_support", "sessionGoal": "\ud559\uad50 \uc77c\uc815 \ubcc0\uacbd \uc548\ub0b4\ub97c \ubcf4\uace0 \uccb4\uc721\uad00 \ub300\uc2e0 \uc0c1\ub2f4\uc2e4\ub85c \uac00\uc57c \ud568\uc744 \ud655\uc778\ud55c \ub4a4, \ud544\uc694\ud558\uba74 \uc9e7\uace0 \ubd84\uba85\ud558\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud55c\ub2e4.", "targetSkill": "\uc77c\uc815 \ubcc0\uacbd \ub2e8\uc11c \ud655\uc778\uacfc \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5 \ub9d0\ud558\uae30", "difficultyPolicy": {"level": "easy_success", "reason": "\uc77d\uae30 \ubd80\ub2f4\uc774 \ub9e4\uc6b0 \ub0ae\uace0 \ub450 \uac00\uc9c0 \uc120\ud0dd\uc774 \uc801\uc808\ud558\ubbc0\ub85c, \uba3c\uc800 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc548\ub0b4 \ub2e8\uc11c\ub97c \ud655\uc778\ud558\uace0 \uc9e7\uc740 \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5\uc73c\ub85c \uc774\uc5b4\uc9c0\uac8c \uad6c\uc131\ud569\ub2c8\ub2e4."}, "selectedStrategy": ["\uc131\uacf5 \uba3c\uc800 \uacbd\ud5d8", "\uc9e7\uc740 \uc2dc\uac01 \uc124\uba85", "\ub450 \uac00\uc9c0 \uc120\ud0dd\uc73c\ub85c \uc904\uc774\uae30", "\ub2e8\uacc4\ubcc4 \uc21c\uc11c \ud655\uc778", "\uc9e7\uc740 \ubb38\uc7a5 \ub9d0\ud558\uae30"], "stagePlan": [{"step": 1, "stageRole": "scenario_intro", "templateType": "scenario_intro", "studentTitle": "\uc0c1\ud669 \ub9cc\ub098\uae30", "purpose": "\ud559\uad50 \uc77c\uc815\uc774 \ubc14\ub00c\uc5b4 \uc624\ub298\uc740 \uccb4\uc721\uad00\uc774 \uc544\ub2c8\ub77c \uc0c1\ub2f4\uc2e4\ub85c \uac00\uc57c \ud558\ub294 \uc0c1\ud669\uc744 \ucc28\ubd84\ud788 \uc608\uace0\ud569\ub2c8\ub2e4."}, {"step": 2, "stageRole": "clue_identification", "templateType": "highlight_clue", "studentTitle": "\ub2e8\uc11c \ucc3e\uae30", "purpose": "\uac8c\uc2dc\ud310\uc774\ub098 \uc548\ub0b4 \uc885\uc774\uc5d0\uc11c \ubc14\ub010 \uc7a5\uc18c\ub97c \uc54c\ub824 \uc8fc\ub294 \ub2e8\uc11c \ud558\ub098\ub97c \ucc3e\uac8c \ud569\ub2c8\ub2e4."}, {"step": 3, "stageRole": "action_selection", "templateType": "sequence_ordering", "studentTitle": "\ud589\ub3d9 \uace0\ub974\uae30", "purpose": "\uc548\ub0b4 \ud655\uc778, \uae38\uc774 \ud5f7\uac08\ub9ac\uba74 \uc120\uc0dd\ub2d8\uaed8 \ubb3b\uae30, \uc0c1\ub2f4\uc2e4\ub85c \uc774\ub3d9\ud558\uae30\uc758 \uc21c\uc11c\ub97c \uc9e7\uac8c \uc815\ub9ac\ud569\ub2c8\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_roleplay", "studentTitle": "\ud55c \ubc88 \ud574\ubcf4\uae30", "purpose": "\uc120\uc0dd\ub2d8 \uc5ed\ud560\uc758 \uc0c1\ub300\uc5d0\uac8c \uc0c1\ub2f4\uc2e4 \uc704\uce58\ub97c \uc9e7\uace0 \ubd84\uba85\ud558\uac8c \ubb3c\uc5b4\ubcf4\ub294 \ub9d0\ud558\uae30 \uc5f0\uc2b5\uc744 \ud569\ub2c8\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\ud559\uad50 \ubcf5\ub3c4\uc5d0\uc11c \uc77c\uc815 \ubcc0\uacbd \uc548\ub0b4\ub97c \ubcf4\uace0 \ub2e4\uc74c \uc7a5\uc18c\ub97c \ud655\uc778\ud574\uc57c \ud558\ub294 \uc804\uccb4 \uc0c1\ud669\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\ucd08\ub4f1\ud559\uad50 \uace0\ud559\ub144 \ud559\uc0dd\uc774 \ucc28\ubd84\ud788 \uc11c \uc788\ub294 \ud559\uad50 \ubcf5\ub3c4", "\uac8c\uc2dc\ud310\uc774\ub098 \uc548\ub0b4\ud310\uc774 \uc788\ub294 \uc7a5\uba74", "\uccb4\uc721\uad00 \ubc29\ud5a5\uacfc \uc0c1\ub2f4\uc2e4 \ubc29\ud5a5\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub294 \ubcf5\ub3c4 \ubd84\uc704\uae30", "\ubd88\uc548\ud558\uc9c0 \uc54a\uace0 \uc548\uc804\ud55c \ud559\uad50 \uc0dd\ud65c \uc7a5\uba74"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_1", "scenePurpose": "\uc624\ub298 \uc774\ub3d9 \uc7a5\uc18c\uac00 \ubc14\ub010 \uc0c1\ud