INSERT INTO agent_runs VALUES('agent_run_3b537395-09db-4efa-aabe-cda3cdf36aaa','orchestrator','orchestrator_plan_v1','OrchestratorPlanV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "requestedGoal": "\uc911\ud559\uad50 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \uc77d\uace0 \uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud55c \ub4a4, \uc65c \uadf8\ub807\uac8c \ud310\ub2e8\ud588\ub294\uc9c0 \uadfc\uac70\ub97c \uc9e7\uac8c \uc124\uba85\ud558\ub294 \uc5f0\uc2b5. \ubd84\uc218, \ud53c\uc790, \uc870\uac01 \ubaa8\ub378\uc740 \uc0ac\uc6a9\ud558\uc9c0 \ub9d0\uace0 \uad6d\uc5b4\u00b7\uc815\ubcf4 \uc77d\uae30 \uc18c\uc7ac\ub85c \uad6c\uc131", "contentType": "learning_focus", "caseFile": {"profile": {"id": "student_learning_fraction", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_fraction", "displayName": "\uc774\ubbfc\uc900", "grade": "middle_2", "schoolCode": "8811058", "studentType": "learning_focus", "primaryNeed": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ub2e8\uacc4\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "older", "gradeNumber": "2", "className": "1", "interests": ["\uc694\ub9ac", "\ud0d0\ud5d8"], "readingLoad": "low", "choiceCountLimit": 3, "dashboard": {"attendanceRate": 95, "gradeLabel": "\uc9112", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uace0\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "statusLabel": "\uc790\ub8cc \uac80\ud1a0", "attendanceLabel": "95%", "summaryLine": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \uc808\ucc28\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\ubd84\uc218 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5", "primaryNeedDetail": "\uc804\uccb4\uc640 \ubd80\