, "totalSteps": 4, "stages": [{"id": "stage_learning_fraction_store_discount_1", "missionContentId": "content_learning_fraction_store_discount", "step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "studentInstruction": "\ud559\uad50 \ub9e4\uc810 \uadf8\ub9bc\uc744 \ubcf4\uba70 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019 \uc21c\uc11c\ub97c \uba3c\uc800 \uc0b4\ud3b4\ubd10\uc694.", "templateJson": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_1", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_1", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_1_audio"}, "storyText": "\ud559\uad50 \ub9e4\uc810 \uc9c4\uc5f4\ub300\uc5d0 \uacfc\uc790\uc640 \uc74c\ub8cc\uac00 \ub193\uc5ec \uc788\uace0, \uac00\uaca9\ud45c \uc606\uc5d0 \ud560\uc778 \ud45c\uc2dc\uac00 \ubd99\uc5b4 \uc788\uc5b4\uc694. \ud55c \ud559\uc0dd\uc774 \uac00\uaca9\ud45c\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uc9da\uc5b4 \ubcf4\uba70 \uc5bc\ub9c8\ub098 \ub0b4\uc57c \ud560\uc9c0 \uc0dd\uac01\ud558\uace0 \uc788\uc5b4\uc694.", "missionText": "\uc774\uc81c \ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0b4 \ub54c, \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0 \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc744 \ud655\uc778\ud55c \ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \ucc28\ub840\ub300\ub85c \uc0b4\ud3b4\ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud574\ubcfc \uac70\uc608\uc694."}, "realtimeSpec": null, "sortOrder": 1}, {"id": "stage_learning_fraction_store_discount_2", "missionContentId": "content_learning_fraction_store_discount", "step": 2, "stageRole": "basic_problem", "templateType": "sequence_ordering", "studentTitle": "\ubb38\uc81c 1", "studentInstruction": "\ud55c \ubb3c\uac74\uc5d0 \ub300\ud574 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019\uc5d0 \ub9de\uac8c \uce74\ub4dc 3\uc7a5\uc744 \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \ub193\uc544 \ubcf4\uc138\uc694.", "templateJson": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_2", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_2_audio", "question": "\ucf5c\ub77c \ud55c \ubcd1\uc744 \uc0b4 \ub54c, \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uac00\uaca9\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774 \uc88b\uc744\uae4c\uc694? \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \uce74\ub4dc 3\uc7a5\uc744 \ubc30\uc5f4\ud574 \ubcf4\uc138\uc694.", "cards": [{"id": "card_original", "text": "\uc6d0\ub798 \uac00\uaca9\uc744 \ubcf8\ub2e4."}, {"id": "card_discount", "text": "\ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc774 \uc5bc\ub9c8\uc778\uc9c0 \ubcf8\ub2e4."}, {"id": "card_pay", "text": "\ud560\uc778\ub41c \ub4a4\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud55c\ub2e4."}], "answerOrder": ["card_original", "card_discount", "card_pay"], "correctFeedback": "\uc798\ud588\uc5b4\uc694! \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0, \uadf8\ub2e4\uc74c \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc744 \ud655\uc778\ud55c \ub4a4, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud558\uba74 \ub3fc\uc694.", "wrongFeedback": "\ub2e4\uc2dc \ud55c \ubc88 \uc0dd\uac01\ud574\ubcfc\uae4c\uc694? \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0, \uadf8\ub2e4\uc74c \uc5bc\ub9c8\ub098 \uae4e\uc774\ub294\uc9c0 \ubcf4\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud558\ub294 \uc21c\uc11c\uac00 \ub418\ub3c4\ub85d \ubc14\uafd4\ubcf4\uc138\uc694.", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_2", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_2_audio"}}, "realtimeSpec": null, "sortOrder": 2}, {"id": "stage_learning_fraction_store_discount_3", "missionConte