INSERT INTO agent_runs VALUES('agent_run_19d4443a-839e-481f-bb53-db17c9da39e6','content','mission_content_package_v1','MissionContentPackageV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "orchestratorRunId": "agent_run_a070c2ad-1987-4f55-8037-9d9992686035", "orchestratorPlan": {"planVersion": "orchestrator_plan_v1", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "contentType": "learning_focus", "sessionGoal": "\uc911\ud559\uad50 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \uc77d\uace0 \uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud55c \ub4a4, \ud310\ub2e8 \uadfc\uac70\ub97c \uc9e7\uac8c \uc124\uba85\ud55c\ub2e4.", "targetSkill": "\uc9e7\uc740 \uc815\ubcf4 \ubb38\uc7a5\uc5d0\uc11c \ud655\uc778 \uac00\ub2a5\ud55c \ub0b4\uc6a9\uacfc \uc0dd\uac01\u00b7\ub290\ub08c\uc774 \ub2f4\uae34 \ub0b4\uc6a9\uc744 \uad6c\ubd84\ud558\uace0 \uadfc\uac70 \ub9d0\ud558\uae30", "difficultyPolicy": {"level": "easy_success", "reason": "\uad50\uc0ac \uc694\uccad \uc8fc\uc81c\ub97c \uc6b0\uc120\ud558\ub418, \uc77d\uae30 \ubd80\ub2f4\uc774 \ub0ae\uc544\uc57c \ud558\ubbc0\ub85c \uc9e7\uc740 \ud3ec\uc2a4\ud130 \ubb38\uad6c\uc640 3\uac1c \uc774\ud558\uc758 \ubcf4\uae30\ub85c \uccab \uc131\uacf5 \uacbd\ud5d8\uc744 \ub9cc\ub4e4\ub3c4\ub85d \uad6c\uc131\ud569\ub2c8\ub2e4."}, "selectedStrategy": ["\uccab \uc131\uacf5 \uacbd\ud5d8", "\uc9e7\uc740 \uc2dc\uac01 \uc124\uba85", "\ub2e8\uacc4\ubcc4 \ud310\ub2e8", "\ub9d0\ub85c \uc9e7\uac8c \uc815\ub9ac\ud558\uae30"], "stagePlan": [{"step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "purpose": "\ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130\ub97c \uc77d\uc744 \ub54c, \uc22b\uc790\ub098 \ud655\uc778 \uac00\ub2a5\ud55c \ub0b4\uc6a9\uc740 \uc0ac\uc2e4\uc5d0 \uac00\uae5d\uace0 \uc0dd\uac01\uc774\ub098 \uad8c\uc720\uac00 \ub2f4\uae34 \ub9d0\uc740 \uc758\uacac\uc5d0 \uac00\uae5d\ub2e4\ub294 \uae30\uc900\uc744 \uc9e7\uac8c \uc18c\uac1c\ud569\ub2c8\ub2e4."}, {"step": 2, "stageRole": "basic_problem", "templateType": "card_match", "studentTitle": "\ubb38\uc81c 1", "purpose": "\uc9e7\uc740 \ud3ec\uc2a4\ud130 \ubb38\uad6c 3\uac1c\ub97c \uc0ac\uc2e4\uacfc \uc758\uacac\uc73c\ub85c \ub098\ub204\uba70 \uac00\uc7a5 \uc26c\uc6b4 \uad6c\ubd84 \uae30\uc900\uc744 \ud655\uc778\ud569\ub2c8\ub2e4."}, {"step": 3, "stageRole": "applied_problem", "templateType": "explanation_choice", "studentTitle": "\ubb38\uc81c 2", "purpose": "\uc0c8\ub85c\uc6b4 \ud658\uacbd \ucea0\ud398\uc778 \ubb38\uad6c \ud558\ub098\ub97c \ubcf4\uace0 \uc0ac\uc2e4\uc778\uc9c0 \uc758\uacac\uc778\uc9c0 \uace0\ub978 \ub4a4, \uc54c\ub9de\uc740 \ud310\ub2e8 \uadfc\uac70\ub97c \ubcf4\uae30\uc5d0\uc11c \uc120\ud0dd\ud569\ub2c8\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "purpose": "\ud3ec\uc2a4\ud130 \ubb38\uad6c \ud55c\ub450 \uac1c\ub97c \ubcf4\uace0 \uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud55c \uc774\uc720\ub97c \uc790\uc2e0\uc758 \ub9d0\ub85c \uc9e7\uac8c \uc124\uba85\ud574\ubd05\ub2c8\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc911\ud559\uad50 \ubcf5\ub3c4 \uac8c\uc2dc\ud310 \uc55e\uc5d0\uc11c \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uc0c1\ud669\uc744 \ubcf4\uc5ec\uc8fc\uc5b4 \uad6d\uc5b4\u00b7\uc815\ubcf4 \uc77d\uae30 \ud65c\ub3d9 \ubd84\uc704\uae30\ub97c \ub9cc\ub4ed\ub2c8\ub2e4.", "mustShow": ["\uc911\ud559\uad50 \ubcf5\ub3c4 \uac8c\uc2dc\ud310", "\ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130 \uc5ec\ub7ec \uc7a5", "\uc7ac\ud65c\uc6a9 \ud45c\uc2dc\ub098 \ud140\ube14\ub7ec, \ubd84\ub9ac\uc218\uac70\ud568 \uac19\uc740 \uc0dd\ud65c \uc18d \ud658\uacbd \uc18c\uc7ac", "\ud3ec\uc2a4\ud130\ub97c \uc77d\ub294 \uc911\ud559\uc0dd"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_1", "scenePurpose": "\ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc815\ubcf4\uc640 \uc0ac\ub78c\uc758 \uc0dd\uac01\uc774 \ud568\uaed8 \ubcf4\uc77c \uc218 \uc788\uc74c\uc744 \uc7a5\uba74\uc73c\ub85c \uc18c\uac1c\ud569\ub2c8\ub2e4.", "mustShow": ["\uac8c\uc2dc\ud310\uc5d0 \ubd99\uc740 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130", "\ud3ec\uc2a4\ud130\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uc9da\uc5b4 \ubcf4\ub294 \uc911\ud559\uc0dd", "\uc7ac\ud65c\uc6a9\ud488 \uc218\uac70\ud568", "\ud559\uad50 \ubcf5\ub3c4\ub098 \ub3c4\uc11c\uad00 \uc55e \uacf5\uac04"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_2", "scenePurpose": "\uc9e7\uc740 \ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \ubd84\ub958\ud558\ub294 \ud65c\ub3d9\uc758 \ubc30\uacbd\uc774 \ub418\ub294 \uc2e4\uc81c \uac8c\uc2dc\ud310\uacfc \ud658\uacbd \ucea0\ud398\uc778 \uc790\ub8cc\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\ud658\uacbd \ucea0\ud398\uc778 \uac8c\uc2dc\ud310", "\uc11c\ub85c \ub2e4\ub978 \ud3ec\uc2a4\ud130 2~3\uc7a5", "\ubd84\ub9ac\uc218\uac70\ud568\uacfc \uc885\uc774\ucef5, \ud140\ube14\ub7ec \uac19\uc740 \uc2e4\uc81c \ubb3c\uac74", "\uc790\ub8cc\ub97c \ube44\uad50\ud558\uba70 \ubcf4\ub294 \uc911\ud559\uc0dd"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_3", "scenePurpose": "\uc0c8\ub85c\uc6b4 \ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \ubcf4\uace0 \uc65c \uadf8\ub807\uac8c \ud310\ub2e8\ud588\ub294\uc9c0 \uadfc\uac70\ub97c \uace0\ub974\ub294 \ud65c\ub3d9\uc758 \ubc30\uacbd\uc744 \ub9cc\ub4ed\ub2c8\ub2e4.", "mustShow": ["\ud559\uad50 \uc815\ubcf4 \uac8c\uc2dc\ud310", "\ud658\uacbd \ucea0\ud398\uc778 \uc548\ub0b4 \ud3ec\uc2a4\ud130", "\uba54\ubaa8\uc7a5\uc744 \ub4e4\uace0 \uc0dd\uac01\ud558\ub294 \uc911\ud559\uc0dd", "\uc7ac\ud65c\uc6a9 \ub9c8\ud06c\uac00 \uc788\ub294 \uc548\ub0b4\ubb3c"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\ud559\uc0dd\uc774 \uce5c\uad6c\ub098 \uc120\uc0dd\ub2d8\uc5d0\uac8c \ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \uc77d\uace0 \ud310\ub2e8 \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \ud3b8\uc548\ud55c \ub300\ud654 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\uac8c\uc2dc\ud310 \uc55e\uc5d0\uc11c \ub300\ud654\ud558\ub294 \uc911\ud559\uc0dd\uacfc \uc120\uc0dd\ub2d8 \ub610\ub294 \uce5c\uad6c", "\ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130", "\uc124\uba85\uc744 \ub4e3\ub294 \uc0ac\ub78c\uc774 \uace0\uac1c\ub97c \ub044\ub355\uc774\ub294 \ubaa8\uc2b5", "\ucc28\ubd84\ud55c \ud559\uad50 \ubcf5\ub3c4 \ubd84\uc704\uae30"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\uc624\ub298\uc740 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \uc77d\uace0 \uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud574\ubcf4\ub294 \ud65c\ub3d9\uc784\uc744 \uc9e7\uace0 \ud3b8\uc548\ud558\uac8c \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "reassuring"}, {"assetRole": "stage_1", "voicePurpose": "\uc0ac\uc2e4\uc740 \ud655\uc778\ud560 \uc218 \uc788\ub294 \ub0b4\uc6a9, \uc758\uacac\uc740 \uc0dd\uac01\uc774\ub098 \ub290\ub08c\uc774 \ub2f4\uae34 \ub9d0\uc774\ub77c\ub294 \uae30\uc900\uc744 \uc9e7\uac8c \uc124\uba85\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_2", "voicePurpose": "\ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \ud558\ub098\uc529 \uc77d\uace0 \uc0ac\uc2e4\uc778\uc9c0 \uc758\uacac\uc778\uc9c0 \ucc28\ubd84\ud788 \ub098\ub204\ub3c4\ub85d \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "bright"}, {"assetRole": "stage_3", "voicePurpose": "\uc0c8 \ubb38\uad6c\ub97c \uc77d\uace0 \ud310\ub2e8\ud55c \ub4a4, \uc65c \uadf8\ub807\uac8c \uc0dd\uac01\ud588\ub294\uc9c0 \uadfc\uac70\ub97c \uace0\ub974\ub3c4\ub85d \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\uc815\ub2f5\ub9cc \ub9d0\ud558\uae30\ubcf4\ub2e4 \u2018\ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc11c\u2019 \ub610\ub294 \u2018\uc0dd\uac01\uc774 \ub2f4\uaca8 \uc788\uc5b4\uc11c\u2019\ucc98\ub7fc \uc774\uc720\ub97c \uc9e7\uac8c \ub9d0\ud574\ubcf4\ub3c4\ub85d \uaca9\ub824\ud569\ub2c8\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\uad50\uc0ac \uc694\uccad\uc5d0 \ub530\ub77c \ubd84\uc218, \ud53c\uc790, \uc870\uac01 \ubaa8\ub378\uc774 \uc804\ud600 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc558\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uc9112 \ud559\uc0dd\uc5d0\uac8c \uc5b4\uc6b8\ub9ac\ub294 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130 \uc18c\uc7ac\uc774\uba74\uc11c \ubb38\uc7a5\uc740 \uc9e7\uace0 \uc77d\uae30 \ubd80\ub2f4\uc774 \ub0ae\uc740\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uc0ac\uc2e4\uacfc \uc758\uacac\uc758 \uad6c\ubd84 \uae30\uc900\uc774 \u2018\ud655\uc778 \uac00\ub2a5\uc131\u2019\uacfc \u2018\uc0dd\uac01\u00b7\ub290\ub08c\u00b7\uad8c\uc720 \ud45c\ud604\u2019\uc73c\ub85c \ubd84\uba85\ud788 \ub4dc\ub7ec\ub098\ub294\uc9c0 \ubd10\uc8fc\uc138\uc694.", "2\ub2e8\uacc4\ub294 \ubd84\ub958 \ud65c\ub3d9, 3\ub2e8\uacc4\ub294 \ud310\ub2e8 \uadfc\uac70 \uc120\ud0dd \ud65c\ub3d9\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc758 \uc5f0\uc2b5\uc774 \ub418\ub3c4\ub85d \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uc774\ubbf8\uc9c0\uc5d0\ub294 \ubb38\uc81c \ubb38\uad6c\ub098 \uc120\ud0dd\uc9c0, \uc815\ub2f5\uc774 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uace0 \uc7a5\uba74 \uc790\ub8cc\ub85c\ub9cc \uc0ac\uc6a9\ub418\ub294\uc9c0 \uc810\uac80\ud574\uc8fc\uc138\uc694."], "safetyNotes": ["\ud559\uad50 \uacf5\uac1c \uc815\ubcf4\ub294 \uc7a5\uba74 \ub9e5\ub77d\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uace0 \ud559\uc0dd \uac1c\uc778 \ub2a5\ub825 \ud310\ub2e8 \uadfc\uac70\ub85c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\ud559\uc0dd\uc5d0\uac8c \uc9c4\ub2e8\uba85\uc774\ub098 \ub0b4\ubd80 \ud310\ub2e8 \ub77c\ubca8\uc744 \ub178\ucd9c\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\uac1c\uc778\uc815\ubcf4\ub97c \ubb3b\uac70\ub098 \ub9d0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\ud658\uacbd \ucea0\ud398\uc778 \ubb38\uad6c\ub294 \ud2b9\uc815 \ud559\uc0dd\uc774\ub098 \uc2e4\uc81c \uc778\ubb3c\uc744 \ube44\ub09c\ud558\ub294 \ub0b4\uc6a9\uc774 \ub418\uc9c0 \uc54a\ub3c4\ub85d \ud569\ub2c8\ub2e4."]}, "caseFile": {"profile": {"id": "student_learning_fraction", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_fraction", "displayName": "\uc774\ubbfc\uc900", "grade": "middle_2", "schoolCode": "8811058", "studentType": "learning_focus", "primaryNeed": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ub2e8\uacc4\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "older", "gradeNumber": "2", "className": "1", "interests": ["\uc694\ub9ac", "\ud0d0\ud5d8"], "readingLoad": "low", "choiceCountLimit": 3, "dashboard": {"attendanceRate": 95, "gradeLabel": "\uc9112", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uace0\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "statusLabel": "\uc790\ub8cc \uac80\ud1a0", "attendanceLabel": "95%", "summaryLine": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \uc808\ucc28\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\ubd84\uc218 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5", "primaryNeedDetail": "\uc804\uccb4\uc640 \ubd80\ubd84\uc744 \uad6c\ubd84\ud558\uace0 \ubd84\ubaa8\u00b7\ubd84\uc790\uc758 \uc758\ubbf8\ub97c \uc21c\uc11c\ub300\ub85c \uc5f0\uacb0\ud558\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc2dc\uac01 \uc790\ub8cc + \ub2e8\uacc4 \uce74\ub4dc + \ub9d0\ub85c \uc815\ub9ac\ud558\uae30", "supportStrategyDetail": "\uc2dc\uac01 \uc790\ub8cc, \ub2e8\uacc4 \uce74\ub4dc, \ube48\uce78 \ud655\uc778, \ub9d0\ub85c \uc815\ub9ac\ud558\uae30\ub97c \uc0ac\uc6a9\ud574 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ubc18\ubcf5 \uc5f0\uacb0\ud558\ub294 \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uadf8\ub9bc\uc774\ub098 \uc870\uac01 \ubaa8\ub378\uc744 \ubcf4\uba74 \uc804\uccb4\uc640 \ubd80\ubd84\uc744 \ub354 \uc27d\uac8c \uc774\ud574\ud574\uc694.", "\uacfc\uc815\uc744 \uc791\uc740 \ub2e8\uacc4\ub85c \ub098\ub204\uba74 \ub05d\uae4c\uc9c0 \ub530\ub77c\uc62c \uc218 \uc788\uc5b4\uc694.", "\uc694\ub9ac\ub098 \ud0d0\ud5d8\ucc98\ub7fc \uad6c\uccb4\uc801\uc778 \uc18c\uc7ac\uac00 \uc788\uc73c\uba74 \ucc38\uc5ec\uac00 \uc88b\uc544\uc838\uc694."], "weaknesses": ["\ubd84\ubaa8\uc640 \ubd84\uc790\uac00 \uac01\uac01 \ubb34\uc5c7\uc744 \ub73b\ud558\ub294\uc9c0 \uc790\uc8fc \ubc14\uafd4 \uc0dd\uac01\ud574\uc694.", "\ubb38\uc81c \uc124\uba85\uc774 \uae38\uba74 \uc911\uc694\ud55c \uc870\uac74\uc744 \ub193\uce60 \uc218 \uc788\uc5b4\uc694.", "\uc751\uc6a9 \ubb38\uc81c\uc5d0\uc11c\ub294 \uc804\uccb4\ub97c \uba3c\uc800 \ud655\uc778\ud558\ub294 \uc21c\uc11c\uac00 \ud754\ub4e4\ub824\uc694."], "emotionalNote": "\uccab \uc624\ub2f5 \ub4a4\uc5d0\ub3c4 \uc774\uc720\ub97c \uc9e7\uac8c \uc124\uba85\ud558\uba74 \ub2e4\uc2dc \uc2dc\ub3c4\ud569\ub2c8\ub2e4.", "responsePattern": "\uc808\ucc28\ub97c \uce74\ub4dc\ucc98\ub7fc \ub098\ub204\uc5b4 \ubcf4\uc5ec\uc8fc\uba74 \ub530\ub77c\uc624\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \uc790\uae30 \ub9d0\ub85c \uc124\uba85\ud558\ub294 \ub2e8\uacc4\uac00 \ud6a8\uacfc\uc801\uc785\ub2c8\ub2e4.", "guardianCooperation": "\ubcf4\ud638\uc790 \ud611\uc870\ub294 \ubcf4\ud1b5 \uc218\uc900\uc774\uba70, \uac00\uc815 \ubcf5\uc2b5\uc740 \uc9e7\uc740 \uc608\uc2dc 1\uac1c \uc815\ub3c4\uac00 \uc801\ud569\ud569\ub2c8\ub2e4.", "schoolContextNote": "NEIS \uc2dc\uac04\ud45c\uc5d0\uc11c \ucd5c\uadfc \uc218\ud559 \uc218\uc5c5 \ud750\ub984\uc744 \ud655\uc778\ud574 \ubd84\uc218 \ubcf5\uc2b5 \ucf58\ud150\uce20\uc640 \uc5f0\uacb0\ud569\ub2c8\ub2e4.", "nextSessionFocus": ["