INSERT INTO agent_runs VALUES('agent_run_b0323c84-3da3-4f3c-8a4f-95fb985db5f4','content','mission_content_package_v1','MissionContentPackageV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_clock", "caseId": "case_learning_clock", "orchestratorRunId": "agent_run_3c7644f8-e721-43dc-806f-19327e896458", "orchestratorPlan": {"planVersion": "orchestrator_plan_v1", "studentId": "student_learning_clock", "caseId": "case_learning_clock", "contentType": "learning_focus", "sessionGoal": "\ud559\uad50 \uc900\ube44\ubb3c \uc548\ub0b4\ubb38\uc5d0\uc11c \uc624\ub298 \ud45c\uc2dc\uc640 \uc900\ube44\ubb3c \uadf8\ub9bc\uc744 \ucc3e\uc544, \uc624\ub298 \ucc59\uae38 \ubb3c\uac74\uc744 \uc9e7\uac8c \ud655\uc778\ud55c\ub2e4.", "targetSkill": "\uc548\ub0b4\ubb38 \uc18d \uc624\ub298 \ub2e8\uc11c\uc640 \ubb3c\uac74 \uadf8\ub9bc\uc744 \uc5f0\uacb0\ud574 \ud544\uc694\ud55c \uc900\ube44\ubb3c\uc744 \ub9d0\ud558\uae30", "difficultyPolicy": {"level": "easy_success", "reason": "\uae34 \uc9c0\uc2dc\ubcf4\ub2e4 \uadf8\ub9bc \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\uc5d0 \uc798 \ubc18\uc751\ud558\ubbc0\ub85c, \uccab \ub2e8\uacc4\ub294 \uc624\ub298 \ud45c\uc2dc\ub97c \ubc14\ub85c \ucc3e\ub294 \uc26c\uc6b4 \uc131\uacf5\uc73c\ub85c \uc2dc\uc791\ud558\uace0 \uc774\ud6c4 \ubb3c\uac74 \ud655\uc778\uc73c\ub85c \ud55c \uac78\uc74c\ub9cc \ud655\uc7a5\ud569\ub2c8\ub2e4."}, "selectedStrategy": ["\uccab \uc131\uacf5 \uacbd\ud5d8", "\uc9e7\uc740 \uc2dc\uac01 \uc124\uba85", "2\uac1c \uc120\ud0dd\uc9c0", "\ud55c \ubb38\uc7a5 \ud655\uc778"], "stagePlan": [{"step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "purpose": "\uad50\uc2e4 \uac8c\uc2dc\ud310\uc758 \uc900\ube44\ubb3c \uc548\ub0b4\ubb38\uc744 \ubcf4\uace0, \uc624\ub298 \ud45c\uc2dc\uc640 \uc900\ube44\ubb3c \uadf8\ub9bc\uc774 \uc911\uc694\ud55c \ub2e8\uc11c\uc784\uc744 \uc9e7\uac8c \ub9cc\ub0a9\ub2c8\ub2e4."}, {"step": 2, "stageRole": "basic_problem", "templateType": "scene_question", "studentTitle": "\ubb38\uc81c 1", "purpose": "\uc548\ub0b4\ubb38\uc5d0\uc11c \uc624\ub298 \ud45c\uc2dc\ub97c \uba3c\uc800 \ucc3e\uc544, \ubb34\uc5c7\ubd80\ud130 \ubd10\uc57c \ud558\ub294\uc9c0 \uc27d\uac8c \ud655\uc778\ud569\ub2c8\ub2e4."}, {"step": 3, "stageRole": "applied_problem", "templateType": "applied_question", "studentTitle": "\ubb38\uc81c 2", "purpose": "\uc624\ub298 \ud45c\uc2dc \uc606\uc758 \uc900\ube44\ubb3c \uadf8\ub9bc\uc744 \ubcf4\uace0, \uc624\ub298 \ucc59\uae38 \ubb3c\uac74\uc774 \ubb34\uc5c7\uc778\uc9c0 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uace0\ub985\ub2c8\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "purpose": "\uc548\ub0b4\ubb38\uacfc \uac00\ubc29\uc744 \ubcf4\uba70 \uc624\ub298 \ucc59\uae38 \ubb3c\uac74\uc744 \uc9e7\uc740 \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574 \ubd05\ub2c8\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc624\ub298 \ud559\uad50 \uc900\ube44\ubb3c\uc744 \ucc59\uae30\uae30 \uc704\ud574 \uad50\uc2e4 \uc548\ub0b4\ubb38\uacfc \uac00\ubc29\uc744 \ud568\uaed8 \ubcf4\ub294 \uc804\uccb4 \uc0c1\ud669\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\ud55c\uad6d \ucd08\ub4f1\ud559\uad50 \uad50\uc2e4 \uac8c\uc2dc\ud310", "\uc9e7\uc740 \uc548\ub0b4\ubb38 \uc81c\ubaa9 \u2018\uc900\ube44\ubb3c\u2019", "\uc0c9 \uc2a4\ud2f0\ucee4\uac00 \ubd99\uc740 \u2018\uc624\ub298\u2019 \ud45c\uc2dc", "\uc900\ube44\ubb3c \uadf8\ub9bc\uc73c\ub85c \ud06c\uac8c \ubcf4\uc774\ub294 \ub3cb\ubcf4\uae30", "\ucc45\uc0c1 \uc704 \uc5f4\ub9b0 \ucc45\uac00\ubc29\uacfc \uc2e4\uc81c \ub3cb\ubcf4\uae30"], "learningObject": "\uac8c\uc2dc\ud310 \uc900\ube44\ubb3c \uc548\ub0b4\ubb38\uacfc \uc5f4\ub9b0 \ucc45\uac00\ubc29", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \uc5f4\ub9b0 \ucc45\uac00\ubc29\uacfc \uc2e4\uc81c \ub3cb\ubcf4\uae30\ub97c \ub450\uace0, \uc911\uacbd\uc5d0\ub294 \uac8c\uc2dc\ud310 \uc548\ub0b4\ubb38\uc744 \ud06c\uac8c \ubc30\uce58\ud569\ub2c8\ub2e4. \uc548\ub0b4\ubb38\uc5d0\ub294 \uc7a5\uba74 \ub2e8\uc11c\uc778 \u2018\uc900\ube44\ubb3c\u2019\uacfc \u2018\uc624\ub298\u2019\ub9cc \uc9e7\uac8c \ubcf4\uc774\uac8c \ud558\uace0, \ubb38\uc81c\ub098 \uc120\ud0dd\uc9c0\ub294 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud55c\ucabd\uc740 \ud654\uba74 \uc548\ub0b4\uac00 \ub4e4\uc5b4\uac08 \uc218 \uc788\uac8c \ub2e8\uc21c\ud558\uace0 \ube44\uc6cc \ub461\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_1", "scenePurpose": "\uc548\ub0b4\ubb38\uc5d0\ub294 \uc624\ub298 \ubcfc \ud45c\uc2dc\uc640 \ubb3c\uac74 \uadf8\ub9bc\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \ucc98\uc74c \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc785\ub2c8\ub2e4.", "mustShow": ["\uac8c\uc2dc\ud310\uc5d0 \ubd99\uc740 \uc900\ube44\ubb3c \uc548\ub0b4\ubb38", "\uc548\ub0b4\ubb38 \uc704 \uc9e7\uc740 \uc81c\ubaa9 \u2018\uc900\ube44\ubb3c\u2019", "\u2018\uc624\ub298\u2019\uc774\ub77c\uace0 \uc801\ud78c \uc0c9 \ud45c\uc2dc \ub610\ub294 \uc2a4\ud2f0\ucee4", "\ub3cb\ubcf4\uae30 \uadf8\ub9bc", "\uc544\uc9c1 \uc815\ub9ac \uc804\uc778 \uc5f4\ub9b0 \ucc45\uac00\ubc29"], "learningObject": "\uc900\ube44\ubb3c \uc548\ub0b4\ubb38", "compositionHint": "\uc548\ub0b4\ubb38\uc774 \ud654\uba74 \uc911\uc2ec\uc744 \ucc28\uc9c0\ud558\ub294 \uac00\uae4c\uc6b4 \uc7a5\uba74\uc73c\ub85c \uad6c\uc131\ud569\ub2c8\ub2e4. \uc804\uacbd\uc740 \uc548\ub0b4\ubb38, \uc544\ub798\ucabd\uc5d0\ub294 \uc5f4\ub9b0 \uac00\ubc29\uc774 \uc0b4\uc9dd \ubcf4\uc774\uac8c \ud558\uc5ec \uc624\ub298 \ucc59\uae38 \ubb3c\uac74\uc744 \ucc3e\ub294 \uc774\uc57c\uae30 \ud750\ub984\uc744 \ub9cc\ub4ed\ub2c8\ub2e4. \ubc30\uacbd \uad50\uc2e4 \ubb3c\uac74\uc740 \ud750\ub9ac\uac8c \ucc98\ub9ac\ud569\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_2", "scenePurpose": "\ud559\uc0dd\uc774 \uc548\ub0b4\ubb38\uc5d0\uc11c \uc624\ub298 \ud45c\uc2dc\ub97c \uba3c\uc800 \ucc3e\ub294 \uc26c\uc6b4 \uc131\uacf5 \uc7a5\uba74\uc785\ub2c8\ub2e4.", "mustShow": ["\uac00\uae4c\uc774 \ubcf4\uc774\ub294 \uc900\ube44\ubb3c \uc548\ub0b4\ubb38", "\u2018\uc624\ub298\u2019 \ud45c\uc2dc\uac00 \ub3cb\ubcf4\uc774\ub3c4\ub85d \ubd99\uc740 \uc0c9 \uc2a4\ud2f0\ucee4", "\ub3cb\ubcf4\uae30 \uadf8\ub9bc\uc740 \ubcf4\uc774\uc9c0\ub9cc \uc624\ub298 \ud45c\uc2dc\ubcf4\ub2e4 \ub35c \uac15\uc870", "\uc190\uac00\ub77d\uc774\ub098 \uc5f0\ud544 \ub05d\uc774 \uc624\ub298 \ud45c\uc2dc \uac00\uae4c\uc774\ub97c \uac00\ub9ac\ud0a4\ub294 \ubaa8\uc2b5"], "learningObject": "\uc548\ub0b4\ubb38 \uc18d \uc624\ub298 \ud45c\uc2dc", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \u2018\uc624\ub298\u2019 \ud45c\uc2dc\ub97c \ud06c\uac8c \ub450\uace0 \uc190\uac00\ub77d\uc774\ub098 \uc5f0\ud544 \ub05d\uc774 \ub2e8\uc11c\ub97c \uac00\ub9ac\ud0a4\uac8c \ud569\ub2c8\ub2e4. \uc911\uacbd\uc5d0\ub294 \uac19\uc740 \uc548\ub0b4\ubb38 \uc548\uc758 \ub3cb\ubcf4\uae30 \uadf8\ub9bc\uc774 \ud568\uaed8 \ubcf4\uc5ec \ub2e8\uacc4 3\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4. \ud654\uba74\uc740 \ubcf5\uc7a1\ud558\uc9c0 \uc54a\uac8c \uc720\uc9c0\ud569\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_3", "scenePurpose": "\uc624\ub298 \ud45c\uc2dc \uc606\uc758 \uc900\ube44\ubb3c \uadf8\ub9bc\uc744 \ubcf4\uace0 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ucc59\uaca8\uc57c \ud558\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc785\ub2c8\ub2e4.", "mustShow": ["\uc900\ube44\ubb3c \uc548\ub0b4\ubb38 \uc77c\ubd80", "\u2018\uc624\ub298\u2019 \ud45c\uc2dc", "\uc624\ub298 \ud45c\uc2dc \uac00\uae4c\uc774\uc5d0 \uc788\ub294 \ub3cb\ubcf4\uae30 \uadf8\ub9bc", "\ucc45\uc0c1 \uc704 \uc5f4\ub9b0 \ucc45\uac00\ubc29", "\uac00\ubc29 \uc548 \ub610\ub294 \ubc14\ub85c \uc55e\uc758 \uc2e4\uc81c \ub3cb\ubcf4\uae30"], "learningObject": "\ub3cb\ubcf4\uae30 \uadf8\ub9bc\uacfc \uc2e4\uc81c \ub3cb\ubcf4\uae30", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \uc2e4\uc81c \ub3cb\ubcf4\uae30\uac00 \ubcf4\uc774\ub294 \uc5f4\ub9b0 \uac00\ubc29\uc744 \ub450\uace0, \uc911\uacbd\uc5d0\ub294 \uc548\ub0b4\ubb38\uc758 \u2018\uc624\ub298\u2019 \ud45c\uc2dc\uc640 \ub3cb\ubcf4\uae30 \uadf8\ub9bc\uc774 \ud568\uaed8 \ubcf4\uc774\uac8c \ud569\ub2c8\ub2e4. \ud559\uc0dd\uc774 \uadf8\ub9bc \ub2e8\uc11c\uc640 \uc2e4\uc81c \ubb3c\uac74\uc744 \uc5f0\uacb0\ud560 \uc218 \uc788\ub3c4\ub85d \ub450 \ub300\uc0c1\uc774 \uac19\uc740 \uc2dc\uc57c \uc548\uc5d0 \ub4e4\uc5b4\uc624\uac8c \ud569\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\uc548\ub0b4\ubb38\uacfc \uac00\ubc29\uc744 \ubcf4\uba70 \uc624\ub298 \ucc59\uae38 \ubb3c\uac74\uc744 \ub9d0\ub85c \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc785\ub2c8\ub2e4.", "mustShow": ["\ucc45\uc0c1 \uc704\uc5d0 \ub193\uc778 \uc900\ube44\ubb3c \uc548\ub0b4\ubb38", "\uc548\ub0b4\ubb38 \uc18d \u2018\uc624\ub298\u2019 \ud45c\uc2dc", "\uc548\ub0b4\ubb38 \uc18d \ub3cb\ubcf4\uae30 \uadf8\ub9bc", "\uc5f4\ub9b0 \ucc45\uac00\ubc29 \uc548\uc758 \uc2e4\uc81c \ub3cb\ubcf4\uae30", "\uc606\uc5d0\uc11c \uae30\ub2e4\ub824 \uc8fc\ub294 \uad50\uc0ac\ub098 \uce5c\uad6c\uc758 \uc190\uc9d3"], "learningObject": "\uc548\ub0b4\ubb38 \ub2e8\uc11c\uc640 \uac00\ubc29 \uc18d \uc900\ube44\ubb3c", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \uc548\ub0b4\ubb38\uacfc \uc5f4\ub9b0 \uac00\ubc29\uc744 \ub098\ub780\ud788 \ubc30\uce58\ud574 \ub9d0\ud558\uae30 \uc804\uc5d0 \ubc14\ub85c \ubcfc \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4. \uc0ac\ub78c\uc740 \uc606\ubaa8\uc2b5\uc774\ub098 \uc190\uc9d3 \uc815\ub3c4\ub85c \uc791\uac8c \ub123\uace0, \ud559\uc2b5 \ub300\uc0c1\uc778 \uc548\ub0b4\ubb38\uacfc \ub3cb\ubcf4\uae30\uac00 \uc911\uc2ec\uc774 \ub418\uac8c \ud569\ub2c8\ub2e4. \ub9d0\ud48d\uc120\uc774\ub098 \ub300\uc0ac\ub294 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\uc624\ub298\uc740 \uc548\ub0b4\ubb38\uc744 \ubcf4\uace0 \uc900\ube44\ubb3c\uc744 \ucc59\uae30\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4\uace0 \uc9e7\uace0 \ud3b8\uc548\ud558\uac8c \uc54c\ub824\uc90d\ub2c8\ub2e4.", "tone": "reassuring"}, {"assetRole": "stage_1", "voicePurpose": "\uac8c\uc2dc\ud310 \uc548\ub0b4\ubb38\uc5d0\uc11c \uc624\ub298 \ud45c\uc2dc\uc640 \ubb3c\uac74 \uadf8\ub9bc\uc744 \ud568\uaed8 \ubcfc \uac83\uc784\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_2", "voicePurpose": "\uba3c\uc800 \uc624\ub298 \ud45c\uc2dc\ub9cc \ucc3e\uc544\ubcf4\uba74 \ub41c\ub2e4\uace0 \ub9d0\ud574 \uccab \uc120\ud0dd \ubd80\ub2f4\uc744 \ub0ae\ucda5\ub2c8\ub2e4.", "tone": "reassuring"}, {"assetRole": "stage_3", "voicePurpose": "\uc624\ub298 \ud45c\uc2dc \uc606 \uadf8\ub9bc\uc744 \ubcf4\uace0 \ucc59\uae38 \ubb3c\uac74\uc744 \uace0\ub974\ub3c4\ub85d \uc9e7\uac8c \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\uc624\ub298 \ucc59\uae38 \ubb3c\uac74\uc744 \uc9e7\uac8c \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4\uace0 \uaca9\ub824\ud569\ub2c8\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\ud559\uc0dd\uc5d0\uac8c \ubcf4\uc774\ub294 \uc9c0\uc2dc\ubb38\uc774 \ud55c \ubb38\uc7a5 \uc911\uc2ec\uc73c\ub85c \uc9e7\uac8c \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ub2e8\uacc4 2\uc640 \ub2e8\uacc4 3\uc758 \uc120\ud0dd\uc9c0\uac00 \uac01\uac01 2\uac1c\ub97c \ub118\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc548\ub0b4\ubb38 \uc18d \uc7a5\uba74 \uae00\uc790\ub294 \u2018\uc900\ube44\ubb3c\u2019, \u2018\uc624\ub298\u2019\ucc98\ub7fc \uaf2d \ud544\uc694\ud55c \uc9e7\uc740 \ub2e8\uc11c\ub9cc \ub0a8\uacbc\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc624\ub298 \ud45c\uc2dc\uc640 \ub3cb\ubcf4\uae30 \uadf8\ub9bc, \uc2e4\uc81c \ub3cb\ubcf4\uae30\uac00 \ub2e8\uacc4 1\ubd80\ud130 \ub2e8\uacc4 4\uae4c\uc9c0 \uac19\uc740 \uc774\uc57c\uae30\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ub9c8\uc9c0\ub9c9 \ub9d0\ud558\uae30 \ubaa9\ud45c\uac00 \u2018\uc624\ub298 \ucc59\uae38 \ubb3c\uac74\uc740 \ub3cb\ubcf4\uae30\uc608\uc694.\u2019 \uc815\ub3c4\uc758 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ucda9\ubd84\ud55c\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694."], "safetyNotes": ["\uc774\ubbf8\uc9c0\uc5d0\ub294 \ubb38\uc81c \ubb38\uc7a5, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8\ub97c \ub123\uc9c0 \uc54a\uace0 \uc7a5\uba74 \ub2e8\uc11c\ub9cc \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "\ud559\uad50 \uacf5\uac1c \uc815\ubcf4\ub294 \ubc30\uacbd \ub9e5\ub77d\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uba70 \ud559\uc0dd \uac1c\uc778 \ub2a5\ub825\uc744 \ucd94\uc815\ud558\ub294 \uadfc\uac70\ub85c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\ud559\uc0dd\uc5d0\uac8c \uc9c4\ub2e8\uba85, \uac80\uc0ac \uacb0\uacfc, \uac1c\uc778\uc815\ubcf4\ub97c \ub9d0\ud558\uac8c \ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\uc624\ub2f5 \ub4a4\uc5d0\ub294 \uc9e7\uace0 \ubd80\ub4dc\ub7ec\uc6b4 \uc7ac\uc2dc\ub3c4 \uc548\ub0b4\ub9cc \uc81c\uacf5\ud569\ub2c8\ub2e4."]}, "caseFile": {"profile": {"id": "student_learning_clock", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_clock", "displayName": "\uae40\uc9c0\uc6b0", "grade": "elementary_3", "schoolCode": "8811046", "studentType": "learning_focus", "primaryNeed": "\uc2dc\uac04 \uc77d\uae30 \uae30\ucd08\ub97c \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "younger", "gradeNumber": "3", "className": "1", "readingLoad": "very_low", "choiceCountLimit": 2, "dashboard": {"attendanceRate": null, "gradeLabel": "\ucd083", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "statusLabel": "\uc790\ub8cc \uc0dd\uc131", "attendanceLabel": "\uae30\ub85d \uc804", "summaryLine": "\uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc2dc\uac04 \uc77d\uae30 \uae30\ucd08\ub97c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\uc2dc\uac04 \uc77d\uae30 \uae30\ucd08 \ubcf4\uc644 \uc218\uc5c5", "primaryNeedDetail": "\uae34 \uc124\uba85\ubcf4\ub2e4 \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\ub85c \uc2dc\uce68\uacfc \ubd84\uce68\uc744 \uad6c\ubd84\ud558\uace0 \uc77d\ub294 \uc21c\uc11c\ub97c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc2dc\uac01 \ub2e8\uc11c \uae30\ubc18 2\uc9c0\uc120\ub2e4 \uc218\uc5c5", "supportStrategyDetail": "\ud55c \ubb38\uc7a5 \uc9c0\uc2dc, \ud070 \uadf8\ub9bc \ub2e8\uc11c, 2\uac1c \uc120\ud0dd\uc9c0\ub97c \uc0ac\uc6a9\ud574 \uc2dc\uac04 \uc77d\uae30 \uc21c\uc11c\ub97c \uc548\uc815\ud654\ud558\ub294 \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uadf8\ub9bc\uc5d0\uc11c \uc911\uc694\ud55c \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uc73c\uba74 \ubc14\ub85c \ubc18\uc751\ud574\uc694.", "\uc120\ud0dd\uc9c0\uac00 2\uac1c\uc77c \ub54c \ubd80\ub2f4\uc774 \uc904\uace0 \uc548\uc815\uc801\uc73c\ub85c \uace0\ub97c \uc218 \uc788\uc5b4\uc694.", "\ub9c8\uc2a4\ucf54\ud2b8\uac00 \uc9e7\uac8c \uc548\ub0b4\ud558\uba74 \uc2dc\uc120\uc744 \uc798 \ubaa8\uc544\uc694."], "weaknesses": ["\ubb38\uc7a5\uc774 \uae38\uc5b4\uc9c0\uba74 \ubb34\uc5c7\ubd80\ud130 \ud574\uc57c \ud560\uc9c0 \uba48\uce6b\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc2dc\uacc4\ub97c \uc77d\uc744 \ub54c \uc9e7\uc740 \ubc14\ub298\ubd80\ud130 \ubd10\uc57c \ud558\ub294 \uc21c\uc11c\uac00 \ud754\ub4e4\ub824\uc694.", "\ud2c0\ub9b0 \ub4a4\uc5d0\ub294 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uae30\uae4c\uc9c0 \uc2dc\uac04\uc774 \uc870\uae08 \ud544\uc694\ud574\uc694."], "emotionalNote": "\ucc98\uc74c \ubb38\ud56d\uc5d0\uc11c \uc131\uacf5 \uacbd\ud5d8\uc744 \uc5bb\uc73c\uba74 \uc774\ud6c4 \ucc38\uc5ec\uac00 \uc548\uc815\ub429\ub2c8\ub2e4.", "responsePattern": "\uadf8\ub9bc\uc744 \uba3c\uc800 \ubcf4\uace0, \ud55c \ubb38\uc7a5 \uc9c0\uc2dc\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub97c \ubc1b\uc744 \ub54c \ubc18\uc751\uc774 \uac00\uc7a5 \uc88b\uc2b5\ub2c8\ub2e4.", "guardianCooperation": "\ubcf4\ud638\uc790\ub294 \uac00\uc815\uc5d0\uc11c \uc9e7\uc740 \uc2dc\uacc4 \uc77d\uae30 \uc5f0\uc2b5\uc744 \ub3c4\uc6b8 \uc218 \uc788\uc73c\ub098, \uae34 \ud559\uc2b5\uc9c0\ub294 \ubd80\ub2f4\uc774 \ud07d\ub2c8\ub2e4.", "schoolContextNote": "NEIS \ud559\uad50 \uae30\ubcf8\uc815\ubcf4\uc640 \uc2dc\uac04\ud45c\ub97c \uc5f0\uacb0\ud574 \ud559\uad50 \uc218\uc5c5 \ud750\ub984\uacfc \ud68c\uae30 \ubaa9\ud45c\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.", "nextSessionFocus": ["\uc2dc\uac04 \uc77d\uae30 \uc21c\uc11c \uc775\ud788\uae30", "2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc815\uac01 \uc2dc\uac04 \ud655\uc778\ud558\uae30", "\uccab \ubb38\ud56d\uc740 \uc26c\uc6b4 \uc131\uacf5 \uacbd\ud5d8\uc73c\ub85c \uc2dc\uc791"], "aiContextSummary": "\ucd083 \uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615 \ud559\uc0dd. \uc2dc\uac04 \uc77d\uae30 \uae30\ucd08 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694. \uae34 \ubb38\uc7a5 \uc124\uba85\ubcf4\ub2e4 \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uc131\uacf5 \uacbd\ud5d8\ud615 \ucf58\ud150\uce20\ub85c \uc2dc\uc791\ud558\uba74 \uc88b\uaca0\uc5b4\uc694."}}, "status": "active", "gradeLabel": "\ucd083", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "attendanceRate": null, "attendanceLabel": "\uae30\ub85d \uc804", "strengths": ["\uadf8\ub9bc\uc5d0\uc11c \uc911\uc694\ud55c \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uc73c\uba74 \ubc14\ub85c \ubc18\uc751\ud574\uc694.", "\uc120\ud0dd\uc9c0\uac00 2\uac1c\uc77c \ub54c \ubd80\ub2f4\uc774 \uc904\uace0 \uc548\uc815\uc801\uc73c\ub85c \uace0\ub97c \uc218 \uc788\uc5b4\uc694.", "\ub9c8