ackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc601\uc5b4 \uc218\uc5c5 \uc2dc\uac04\uc5d0 \ud559\uad50 \ubcf5\ub3c4 \ud658\uacbd \uc548\ub0b4\ubb38\uc744 \ud568\uaed8 \uc77d\ub294 \uc804\uccb4 \ubd84\uc704\uae30\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\uc911\ud559\uad50 \ubcf5\ub3c4 \uac8c\uc2dc\ud310", "\uc601\uc5b4 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130", "\uc7ac\ud65c\uc6a9\ud568", "\ud140\ube14\ub7ec\uc640 \uc885\uc774\ucef5", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cBring your tumbler.\u201d, \u201cPaper cups: 20 today.\u201d"], "learningObject": "\uc601\uc5b4 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \uc601\uc5b4 \ud3ec\uc2a4\ud130\uc640 \uc7ac\ud65c\uc6a9\ud568\uc774 \uc798 \ubcf4\uc774\uac8c \ub450\uace0, \uc911\uac04\uc5d0\ub294 \ud3ec\uc2a4\ud130\ub97c \uc77d\ub294 \uc911\ud559\uc0dd\uc744 \uc791\uac8c \ubc30\uce58\ud569\ub2c8\ub2e4. \ud654\uba74 \ud55c\ucabd\uc740 \ud559\uc2b5 \ud654\uba74\uc774 \uc62c\ub77c\uac08 \uc218 \uc788\uac8c \uc5ec\ubc31\uc744 \ub461\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_1", "scenePurpose": "\uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5 \ub450 \uac1c\ub97c \ubcf4\uace0 \ud655\uc778 \uac00\ub2a5\ud55c \ubb38\uc7a5\uacfc \uc0dd\uac01\u00b7\uad8c\uc720\uac00 \ub2f4\uae34 \ubb38\uc7a5\uc744 \ube44\uad50\ud560 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4.", "mustShow": ["\ud559\uad50 \uc601\uc5b4 \uac8c\uc2dc\ud310", "\ud658\uacbd \uc548\ub0b4 \ud3ec\uc2a4\ud130", "\uc885\uc774\ucef5\uc744 \ubaa8\uc544 \ub454 \uc0c1\uc790", "\ud140\ube14\ub7ec", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cPaper cups: 20 today.\u201d, \u201cUse a tumbler. It is cool.\u201d"], "learningObject": "\uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5\uc774 \uc801\ud78c \ud658\uacbd \uc548\ub0b4 \ud3ec\uc2a4\ud130", "compositionHint": "\uc804\uacbd\uc758 \ud3ec\uc2a4\ud130 \ubb38\uad6c\uac00 \ub610\ub837\ud558\uac8c \ubcf4\uc774\uace0, \uc8fc\ubcc0 \uc0ac\ubb3c\uc740 \ubb38\uc7a5\uc758 \uc758\ubbf8\ub97c \ub3d5\ub294 \uc815\ub3c4\ub85c\ub9cc \ubc30\uce58\ud569\ub2c8\ub2e4. \uc815\ub2f5\uc744 \uc554\uc2dc\ud558\ub294 \ud45c\uc2dc\ub098 \ubd84\ub958 \ub77c\ubca8\uc740 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_2", "scenePurpose": "\ubb38\uc7a5\uc744 \ud310\ub2e8\ud558\uae30 \uc804 \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub3c4\ub85d \uc601\uc5b4 \uac8c\uc2dc\ud310\uc744 \ubc14\ub77c\ubcf4\uba70 \ucc28\uadfc\ucc28\uadfc \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\uc911\ud559\uad50 \ubcf5\ub3c4 \uac8c\uc2dc\ud310", "\uc601\uc5b4 \ud658\uacbd \ud3ec\uc2a4\ud130", "\ud559\uc0dd\uc774 \ud3ec\uc2a4\ud130\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uc9da\ub294 \ubaa8\uc2b5", "\uc7ac\ud65c\uc6a9\ud568 \uc704\uce58\ub97c \ub098\ud0c0\ub0b4\ub294 \uc2e4\uc81c \ubcf5\ub3c4 \uc7a5\uba74", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cRead the sentence.\u201d"], "learningObject": "\uc601\uc5b4 \ubb38\uc7a5 \ud310\ub2e8\uc744 \uc2dc\uc791\ud558\ub294 \uac8c\uc2dc\ud310 \uc790\ub8cc", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \ud3ec\uc2a4\ud130\uc640 \ud559\uc0dd\uc758 \uc190\uc774 \ubcf4\uc774\uace0, \uc911\uac04\uc5d0\ub294 \ubcf5\ub3c4\uc640 \uc7ac\ud65c\uc6a9\ud568\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc774\ub3c4\ub85d \ud569\ub2c8\ub2e4. \uc21c\uc11c \uce74\ub4dc, \ubc88\ud638, \ud654\uc0b4\ud45c \uac19\uc740 \ud65c\ub3d9 \ud654\uba74 \uc694\uc18c\ub294 \uc774\ubbf8\uc9c0\uc5d0 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_3", "scenePurpose": "\uc0c8 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc5d0\uc11c \uc7a5\uc18c \ub2e8\uc11c\ub97c \ud655\uc778\ud574 \ud310\ub2e8 \uadfc\uac70\ub97c \uace0\ub974\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\ubcf5\ub3c4 \uc548\ub0b4 \uac8c\uc2dc\ud310", "1\uce35 \ubcf5\ub3c4\uc5d0 \ub193\uc778 \uc7ac\ud65c\uc6a9\ud568", "\uc704\uce58\ub97c \ud655\uc778\ud558\ub294 \uc911\ud559\uc0dd", "\uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38: \u201cRecycling bins are on the first floor.\u201d"], "learningObject": "\uc7a5\uc18c \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\ub294 \uc601\uc5b4 \uc548\ub0b4\ubb38", "compositionHint": "\uc804\uacbd\uc758 \uc548\ub0b4\ubb38 \ubb38\uad6c\uc640 \uc2e4\uc81c \uc7ac\ud65c\uc6a9\ud568\uc774 \ud568\uaed8 \ubcf4\uc774\uac8c \ud558\uace0, \ubc30\uacbd\uc740 \ubcf5\ub3c4\uc784\uc744 \uc54c \uc218 \uc788\uc744 \uc815\ub3c4\ub85c\ub9cc \ub2e8\uc21c\ud558\uac8c \uc720\uc9c0\ud569\ub2c8\ub2e4. \uc120\ud0dd\uc9c0\ub098 \uc815\ub2f5 \ud45c\uc2dc\ub294 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\uce5c\uad6c\uc5d0\uac8c \uc601\uc5b4 \uc548\ub0b4\ubb38 \ud310\ub2e8 \uc774\uc720\ub97c \uc9e7\uac8c \uc124\uba85\ud558\ub294 \ub9d0\ud558\uae30 \uc0c1\ud669\uc744 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\uc601\uc5b4 \ud658\uacbd \ud3ec\uc2a4\ud130 \uc55e\uc758 \uc911\ud559\uc0dd \ub450 \uba85", "\ud55c \ud559\uc0dd\uc774 \ud3ec\uc2a4\ud130\ub97c \uac00\ub9ac\ud0a4\uace0 \ub2e4\ub978 \ud559\uc0dd\uc774 \ub4e3\ub294 \ubaa8\uc2b5", "\uc7ac\ud65c\uc6a9\ud568\uacfc \ud140\ube14\ub7ec", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cPaper cups: 20 today.\u201d, \u201cUse a tumbler.\u201d"], "learningObject": "\uc124\uba85\uc758 \uadfc\uac70\uac00 \ub418\ub294 \uc601\uc5b4 \ud658\uacbd \ud3ec\uc2a4\ud130", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \ud3ec\uc2a4\ud130\uc640 \uc124\uba85\ud558\ub294 \uc190\uc9d3\uc774 \ubcf4\uc774\uace0, \ub450 \ud559\uc0dd\uc740 \uacfc\uc7a5\ub418\uc9c0 \uc54a\uc740 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ub300\ud654 \uc790\uc138\ub85c \ubc30\uce58\ud569\ub2c8\ub2e4. \ub9d0\ud48d\uc120\uc774\ub098 \ub300\ud654 \ubb38\uc7a5\uc740 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\uc624\ub298 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \uc77d\uace0 \ud655\uc778\ud560 \uc218 \uc788\ub294 \ub9d0\uacfc \uc0dd\uac01\uc774 \ub2f4\uae34 \ub9d0\uc744 \ub098\ub204\uc5b4 \ubcfc \uac83\uc784\uc744 \ud3b8\uc548\ud558\uac8c \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_1", "voicePurpose": "\uc601\uc5b4 \ubb38\uc7a5 \uc18d \uc22b\uc790\ub098 \uc7a5\uc18c\ub294 \ud655\uc778 \ub2e8\uc11c\uac00 \ub420 \uc218 \uc788\uace0, \uba4b\uc9c0\ub2e4\u00b7\ud558\uc790 \uac19\uc740 \ud45c\ud604\uc740 \uc0dd\uac01\uc774\ub098 \uad8c\uc720\uac00 \ub420 \uc218 \uc788\uc74c\uc744 \uc9e7\uac8c \uc124\uba85\ud569\ub2c8\ub2e4.", "tone": "reassuring"}, {"assetRole": "stage_2", "voicePurpose": "\ubb38\uc7a5\uc744 \ubc14\ub85c \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uc77d\uace0, \ub2e8\uc11c\ub97c \ucc3e\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \ub9d0\ud558\ub294 \uc21c\uc11c\ub85c \ucc9c\ucc9c\ud788 \ud574 \ubcf4\uc790\uace0 \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_3", "voicePurpose": "\uc0c8 \uc601\uc5b4 \ubb38\uc7a5\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc7a5\uc18c \ub2e8\uc11c\uac00 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uace0 \uadfc\uac70\ub97c \uace0\ub974\ub3c4\ub85d \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "bright"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\uce5c\uad6c\uc5d0\uac8c \uc9e7\uac8c \uc124\uba85\ud574 \ubcf4\ub294 \ub2e8\uacc4\uc774\uba70, \u2018\ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc11c\u2019 \ub610\ub294 \u2018\uc0dd\uac01\uc774 \ub2f4\uaca8 \uc788\uc5b4\uc11c\u2019\ucc98\ub7fc \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4\uace0 \uaca9\ub824\ud569\ub2c8\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\uad50\uc0ac \uc694\uccad\uc5d0 \ub9de\uac8c \uc601\uc5b4 \uc218\uc5c5 \uc8fc\uc81c\ub85c \uc804\ud658\ub418\uc5c8\uace0, \uae30\uc874 \uad6d\uc5b4 \ubaa9\ud45c\ub294 \uc9c0\uc6d0 \ubc29\uc2dd\uc73c\ub85c\ub9cc \ud65c\uc6a9\ub418\uc5c8\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uc601\uc5b4 \ubb38\uc7a5\uc774 \uc9112 \ud559\uc0dd\uc5d0\uac8c \ub108\ubb34 \uc720\uce58\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc77d\uae30 \ubd80\ub2f4\uc774 \ub0ae\uc740\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "2\ub2e8\uacc4\ub294 \uc21c\uc11c \uc815\ub9ac, 3\ub2e8\uacc4\ub294 \ud310\ub2e8 \uadfc\uac70 \uc120\ud0dd\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \uc5f0\uc2b5 \ubc29\uc2dd\uc774 \ub418\ub3c4\ub85d \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \ubd10\uc8fc\uc138\uc694.", "\uc774\ubbf8\uc9c0\uc5d0\ub294 \ud65c\ub3d9 \ud654\uba74\uc758 \uc120\ud0dd\uc9c0\ub098 \uc815\ub2f5\uc774 \uc544\ub2c8\ub77c \uc7a5\uba74 \uc18d \uc9e7\uc740 \uc601\uc5b4 \uc790\ub8cc\ub9cc \ub4e4\uc5b4\uac00\ub294\uc9c0 \uc810\uac80\ud574\uc8fc\uc138\uc694.", "\ub9c8\uc9c0\ub9c9 \ub9d0\ud558\uae30 \ub2e8\uacc4\uac00 \uc55e \ub2e8\uacc4\uc758 \ud310\ub2e8 \uae30\uc900\uc744 \uadf8\ub300\ub85c \uc0ac\uc6a9\ud574 \ud55c \ubb38\uc7a5 \uadfc\uac70 \uc124\uba85\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694."], "safetyNotes": ["\ud559\uc0dd\uc758 \uac1c\uc778 \ub2a5\ub825\uc774\ub098 \uc9c4\ub2e8\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ud45c\ud604\uc740 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\ud559\uad50 \uacf5\uac1c \uc815\ubcf4\ub294 \uc7a5\uba74 \ub9e5\ub77d\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uace0 \ud559\uc0dd \uac1c\uc778 \ud2b9\uc131 \ud310\ub2e8\uc5d0\ub294 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\uc774\ubbf8\uc9c0\uc5d0\ub294 \ubb38\uc81c \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8\ub97c \ub123\uc9c0 \uc54a\uace0 \ud544\uc694\ud55c \ubb38\uc7a5 \uc790\ub8cc\ub294 \uc9e7\uc740 \uc7a5\uba74 \ubb38\uad6c\ub85c\ub9cc \uc81c\ud55c\ud569\ub2c8\ub2e4.", "\uc601\uc5b4 \ubb38\uc7a5 \uc218\ub97c \uc801\uac8c \uc720\uc9c0\ud574 \uc77d\uae30 \ubd80\ub2f4\uc744 \ub0ae\ucda5\ub2c8\ub2e4."]}','gpt-5.5','succeeded','{"input_tokens": 24123, "input_tokens_details": {"cached_tokens": 0}, "output_tokens": 3314, "output_tokens_details": {"reasoning_tokens": 1034}, "total_tokens": 27437}',NULL,NULL,0,'2026-05-04T17:59:23.851715+00:00','2026-05-04T18:00:19.932069+00:00');
INSERT INTO agent_runs VALUES('agent_run_1342d82f-1977-44ef-be81-9d0a1de7eca8','content','mission_content_package_v1','MissionContentPackageV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "orchestratorRunId": "agent_run_c64d07ad-386f-4586-8c88-bd904b5271d9", "orchestratorPlan": {"planVersion": "orchestrator_plan_v1", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "contentType": "learning_focus", "sessionGoal": "\uc601\uc5b4 \ud658\uacbd \uc548\ub0b4\ubb38 \uc18d \uc9e7\uc740 \ubb38\uc7a5\uc744 \ubcf4\uace0 \ud655\uc778 \uac00\ub2a5\ud55c \uc815\ubcf4\uc640 \uc0dd\uac01\uc774 \ub2f4\uae34 \ud45c\ud604\uc744 \uad6c\ubd84\ud55c \ub4a4, \ud310\ub2e8 \uadfc\uac70\ub97c \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud55c\ub2e4.", "targetSkill": "\uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5\uc5d0\uc11c \uc22b\uc790\u00b7\uc7a5\uc18c\ucc98\ub7fc \ud655\uc778 \uac00\ub2a5\ud55c \ub2e8\uc11c\uc640 \ub290\ub08c\u00b7\uad8c\uc720 \ud45c\ud604\uc744 \uad6c\ubd84\ud558\uace0 \uc774\uc720 \ub9d0\ud558\uae30", "difficultyPolicy": {"level": "easy_success", "reason": "\uc77d\uae30 \ubd80\ub2f4\uc774 \ub0ae\ub3c4\ub85d \uc601\uc5b4 \ubb38\uc7a5\uc740 \uc9e7\uac8c \uc81c\uc2dc\ud558\uace0, \uba3c\uc800 \ud310\ub2e8 \uc21c\uc11c\ub97c \uc815\ub9ac\ud55c \ub4a4 \uc0c8 \ubb38\uc7a5 \ud558\ub098\uc5d0 \uc801\uc6a9\ud558\ub3c4\ub85d \uad6c\uc131\ud569\ub2c8\ub2e4."}, "selectedStrategy": ["\uc131\uacf5 \uba3c\uc800", "\uc9e7\uc740 \uc2dc\uac01 \uc124\uba85", "\ub2e8\uacc4\ubcc4 \uc21c\uc11c \uc815\ub9ac", "\uae30\uc900 \ub2e8\uc11c\ub85c \uadfc\uac70 \ub9d0\ud558\uae30"], "stagePlan": [{"step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "purpose": "\ud559\uad50 \ubcf5\ub3c4 \uc601\uc5b4 \ud658\uacbd \uc548\ub0b4\ubb38\uc744 \ubcf4\uba70, \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc815\ubcf4\uc640 \uc0dd\uac01\uc774 \ub2f4\uae34 \ud45c\ud604\uc758 \ucc28\uc774\ub97c \uc9e7\uac8c \ub9cc\ub0a9\ub2c8\ub2e4."}, {"step": 2, "stageRole": "basic_problem", "templateType": "sequence_ordering", "studentTitle": "\ubb38\uc81c 1", "purpose": "\uc601\uc5b4 \ubb38\uc7a5\uc744 \ud310\ub2e8\ud560 \ub54c \u2018\ubb38\uc7a5 \uc77d\uae30 \u2192 \ud655\uc778 \ub2e8\uc11c \ucc3e\uae30 \u2192 \uc0ac\uc2e4\uc778\uc9c0 \uc758\uacac\uc778\uc9c0 \ub9d0\ud558\uae30\u2019 \uc21c\uc11c\ub97c \uba3c\uc800 \uc548\uc815\uc801\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4."}, {"step": 3, "stageRole": "applied_problem", "templateType": "explanation_choice", "studentTitle": "\ubb38\uc81c 2", "purpose": "\uc0c8 \uc601\uc5b4 \uc548\ub0b4\ubb38 \ud55c \ubb38\uc7a5\uc744 \ubcf4\uace0, \uc7a5\uc18c\ucc98\ub7fc \ud655\uc778 \uac00\ub2a5\ud55c \ub2e8\uc11c\uac00 \uc788\uc5b4\uc11c \uc0ac\uc2e4\uc5d0 \uac00\uae4c\uc6b4\uc9c0 \ud310\ub2e8 \uadfc\uac70\ub97c \uace0\ub985\ub2c8\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "purpose": "\uce5c\uad6c\uac00 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \ud5f7\uac08\ub824 \ud558\ub294 \uc0c1\ud669\uc5d0\uc11c, \ubb38\uc7a5\uc744 \ubcf4\uace0 \ud655\uc778 \uac00\ub2a5\ud55c \ub2e8\uc11c\ub098 \uc0dd\uac01 \ud45c\ud604\uc744 \ub4e4\uc5b4 \uc9e7\uac8c \uc124\uba85\ud569\ub2c8\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc601\uc5b4 \uc218\uc5c5 \uc2dc\uac04\uc5d0 \ud559\uad50 \ubcf5\ub3c4 \ud658\uacbd \uc548\ub0b4\ubb38\uc744 \ud568\uaed8 \uc77d\ub294 \uc804\uccb4 \ubd84\uc704\uae30\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\uc911\ud559\uad50 \ubcf5\ub3c4 \uac8c\uc2dc\ud310", "\uc601\uc5b4 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130", "\uc7ac\ud65c\uc6a9\ud568", "\ud140\ube14\ub7ec\uc640 \uc885\uc774\ucef5", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cBring your tumbler.\u201d, \u201cPaper cups: 20 today.\u201d"], "learningObject": "\uc601\uc5b4 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \uc601\uc5b4 \ud3ec\uc2a4\ud130\uc640 \uc7ac\ud65c\uc6a9\ud568\uc774 \uc798 \ubcf4\uc774\uac8c \ub450\uace0, \uc911\uac04\uc5d0\ub294 \ud3ec\uc2a4\ud130\ub97c \uc77d\ub294 \uc911\ud559\uc0dd\uc744 \uc791\uac8c \ubc30\uce58\ud569\ub2c8\ub2e4. \ud654\uba74 \ud55c\ucabd\uc740 \ud559\uc2b5 \ud654\uba74\uc774 \uc62c\ub77c\uac08 \uc218 \uc788\uac8c \uc5ec\ubc31\uc744 \ub461\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_1", "scenePurpose": "\uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5 \ub450 \uac1c\ub97c \ubcf4\uace0 \ud655\uc778 \uac00\ub2a5\ud55c \ubb38\uc7a5\uacfc \uc0dd\uac01\u00b7\uad8c\uc720\uac00 \ub2f4\uae34 \ubb38\uc7a5\uc744 \ube44\uad50\ud560 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4.", "mustShow": ["\ud559\uad50 \uc601\uc5b4 \uac8c\uc2dc\ud310", "\ud658\uacbd \uc548\ub0b4 \ud3ec\uc2a4\ud130", "\uc885\uc774\ucef5\uc744 \ubaa8\uc544 \ub454 \uc0c1\uc790", "\ud140\ube14\ub7ec", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cPaper cups: 20 today.\u201d, \u201cUse a tumbler. It is cool.\u201d"], "learningObject": "\uc9e7\uc740 \uc601\uc5b4 \ubb38\uc7a5\uc774 \uc801\ud78c \ud658\uacbd \uc548\ub0b4 \ud3ec\uc2a4\ud130", "compositionHint": "\uc804\uacbd\uc758 \ud3ec\uc2a4\ud130 \ubb38\uad6c\uac00 \ub610\ub837\ud558\uac8c \ubcf4\uc774\uace0, \uc8fc\ubcc0 \uc0ac\ubb3c\uc740 \ubb38\uc7a5\uc758 \uc758\ubbf8\ub97c \ub3d5\ub294 \uc815\ub3c4\ub85c\ub9cc \ubc30\uce58\ud569\ub2c8\ub2e4. \uc815\ub2f5\uc744 \uc554\uc2dc\ud558\ub294 \ud45c\uc2dc\ub098 \ubd84\ub958 \ub77c\ubca8\uc740 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_2", "scenePurpose": "\ubb38\uc7a5\uc744 \ud310\ub2e8\ud558\uae30 \uc804 \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub3c4\ub85d \uc601\uc5b4 \uac8c\uc2dc\ud310\uc744 \ubc14\ub77c\ubcf4\uba70 \ucc28\uadfc\ucc28\uadfc \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\uc911\ud559\uad50 \ubcf5\ub3c4 \uac8c\uc2dc\ud310", "\uc601\uc5b4 \ud658\uacbd \ud3ec\uc2a4\ud130", "\ud559\uc0dd\uc774 \ud3ec\uc2a4\ud130\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uc9da\ub294 \ubaa8\uc2b5", "\uc7ac\ud65c\uc6a9\ud568 \uc704\uce58\ub97c \ub098\ud0c0\ub0b4\ub294 \uc2e4\uc81c \ubcf5\ub3c4 \uc7a5\uba74", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cRead the sentence.\u201d"], "learningObject": "\uc601\uc5b4 \ubb38\uc7a5 \ud310\ub2e8\uc744 \uc2dc\uc791\ud558\ub294 \uac8c\uc2dc\ud310 \uc790\ub8cc", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \ud3ec\uc2a4\ud130\uc640 \ud559\uc0dd\uc758 \uc190\uc774 \ubcf4\uc774\uace0, \uc911\uac04\uc5d0\ub294 \ubcf5\ub3c4\uc640 \uc7ac\ud65c\uc6a9\ud568\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc774\ub3c4\ub85d \ud569\ub2c8\ub2e4. \uc21c\uc11c \uce74\ub4dc, \ubc88\ud638, \ud654\uc0b4\ud45c \uac19\uc740 \ud65c\ub3d9 \ud654\uba74 \uc694\uc18c\ub294 \uc774\ubbf8\uc9c0\uc5d0 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_3", "scenePurpose": "\uc0c8 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc5d0\uc11c \uc7a5\uc18c \ub2e8\uc11c\ub97c \ud655\uc778\ud574 \ud310\ub2e8 \uadfc\uac70\ub97c \uace0\ub974\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\ubcf5\ub3c4 \uc548\ub0b4 \uac8c\uc2dc\ud310", "1\uce35 \ubcf5\ub3c4\uc5d0 \ub193\uc778 \uc7ac\ud65c\uc6a9\ud568", "\uc704\uce58\ub97c \ud655\uc778\ud558\ub294 \uc911\ud559\uc0dd", "\uc9e7\uc740 \uc601\uc5b4 \uc548\ub0b4\ubb38: \u201cRecycling bins are on the first floor.\u201d"], "learningObject": "\uc7a5\uc18c \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\ub294 \uc601\uc5b4 \uc548\ub0b4\ubb38", "compositionHint": "\uc804\uacbd\uc758 \uc548\ub0b4\ubb38 \ubb38\uad6c\uc640 \uc2e4\uc81c \uc7ac\ud65c\uc6a9\ud568\uc774 \ud568\uaed8 \ubcf4\uc774\uac8c \ud558\uace0, \ubc30\uacbd\uc740 \ubcf5\ub3c4\uc784\uc744 \uc54c \uc218 \uc788\uc744 \uc815\ub3c4\ub85c\ub9cc \ub2e8\uc21c\ud558\uac8c \uc720\uc9c0\ud569\ub2c8\ub2e4. \uc120\ud0dd\uc9c0\ub098 \uc815\ub2f5 \ud45c\uc2dc\ub294 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\uce5c\uad6c\uc5d0\uac8c \uc601\uc5b4 \uc548\ub0b4\ubb38 \ud310\ub2e8 \uc774\uc720\ub97c \uc9e7\uac8c \uc124\uba85\ud558\ub294 \ub9d0\ud558\uae30 \uc0c1\ud669\uc744 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\uc601\uc5b4 \ud658\uacbd \ud3ec\uc2a4\ud130 \uc55e\uc758 \uc911\ud559\uc0dd \ub450 \uba85", "\ud55c \ud559\uc0dd\uc774 \ud3ec\uc2a4\ud130\ub97c \uac00\ub9ac\ud0a4\uace0 \ub2e4\ub978 \ud559\uc0dd\uc774 \ub4e3\ub294 \ubaa8\uc2b5", "\uc7ac\ud65c\uc6a9\ud568\uacfc \ud140\ube14\ub7ec", "\ud3ec\uc2a4\ud130\uc758 \uc9e7\uc740 \uc601\uc5b4 \uc7a5\uba74 \ubb38\uad6c: \u201cPaper cups: 20 today.\u201d, \u201cUse a tumbler.\u201d"], "learningObject": "\uc124\uba85\uc758 \uadfc\uac70\uac00 \ub418\ub294 \uc601\uc5b4 \ud658\uacbd \ud3ec\uc2a4\ud130", "compositionHint": "\uc804\uacbd\uc5d0\ub294 \ud3ec\uc2a4\ud130\uc640 \uc124\uba85\ud558\ub294 \uc190\uc9d3\uc774 \ubcf4\uc774\uace0, \ub450 \ud559\uc0dd\uc740 \uacfc\uc7a5\ub418\uc9c0 \uc54a\uc740 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ub300\ud654 \uc790\uc138\ub85c \ubc30\uce58\ud569\ub2c8\ub2e4. \ub9d0\ud48d\uc120\uc774\ub098 \ub300\ud654 \ubb38\uc7a5\uc740 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "mustNotShow": ["problem text", "choices", "answer", "hint"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\uc624\ub298 \uc601\uc5b4 \uc548\ub0b4\ubb38\uc744 \uc77d\uace0 \ud655\uc778\ud560 \uc218 \uc788\ub294 \ub9d0\uacfc \uc0dd\uac01\uc774 \ub2f4\uae34 \ub9d0\uc744 \ub098\ub204\uc5b4 \ubcfc \uac83\uc784\uc744 \ud3b8\uc548\ud558\uac8c \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_1", "voicePurpose": "\uc601\uc5b4 \ubb38\uc7a5 \uc18d \uc22b\uc790\ub098 \uc7a5\uc18c\ub294 \ud655\uc778 \ub2e8\uc11c\uac00 \ub420 \uc218 \uc788\uace0, \uba4b\uc9c0\ub2e4\u00b7\ud558\uc790 \uac19\uc740 \ud45c\ud604\uc740 \uc0dd\uac01\uc774\ub098 \uad8c\uc720\uac00 \ub420 \uc218 \uc788\uc74c\uc744 \uc9e7\uac8c \uc124\uba85\ud569\ub2c8\ub2e4.", "tone": "reassuring"}, {"assetRole": "stage_2", "voicePurpose": "\ubb38\uc7a5\uc744 \ubc14\ub85c \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uc77d\uace0, \ub2e8\uc11c\ub97c \ucc3e\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \ub9d0\ud558\ub294 \uc21c\uc11c\ub85c \ucc9c\ucc9c\ud788 \ud574 \ubcf4\uc790\uace0 \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_3", "voicePurpose": "\uc0c8 \uc601\uc5b4 \ubb38\uc7a5\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc7a5\uc18c \ub2e8\uc11c\uac00 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uace0 \uadfc\uac70\ub97c \uace0\ub974\ub3c4\ub85d \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "bright"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\uce5c\uad6c\uc5d0\uac8c \uc9e7\uac8c \uc124\uba85\ud574 \ubcf4\ub294 \ub2e8\uacc4\uc774\uba70, \u2018\ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc11c\u2019 \ub610\ub294 \u2018\uc0dd\uac01\uc774 \ub2f4\uaca8 \uc788\uc5b4\uc11c\u2019\ucc98\ub7fc \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4\uace0 \uaca9\ub824\ud569\ub2c8\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\uad50\uc0ac \uc694\uccad\uc5d0 \ub9de\uac8c \uc601\uc5b4 \uc218\uc5c5 \uc8fc\uc81c\ub85c \uc804\ud658\ub418\uc5c8\uace0, \uae30\uc874 \uad6d\uc5b4 \ubaa9\ud45c\ub294 \uc9c0\uc6d0 \ubc29\uc2dd\uc73c\ub85c\ub9cc \ud65c\uc6a9\ub418\uc5c8\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uc601\uc5b4 \ubb38\uc7a5\uc774 \uc9112 \ud559\uc0dd\uc5d0\uac8c \ub108\ubb34 \uc720\uce58\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc77d\uae30 \ubd80\ub2f4\uc774 \ub0ae\uc740\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "2\ub2e8\uacc4\ub294 \uc21c\uc11c \uc815\ub9ac, 3\ub2e8\uacc4\ub294 \ud310\ub2e8 \uadfc\uac70 \uc120\ud0dd\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \uc5f0\uc2b5 \ubc29\uc2dd\uc774 \ub418\ub3c4\ub85d \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \ubd10\uc8fc\uc138\uc694.", "\uc774\ubbf8\uc9c0\uc5d0\ub294 \ud65c\ub3d9 \ud654\uba74\uc758 \uc120\ud0dd\uc9c0\ub098 \uc815\ub2f5\uc774 \uc544\ub2c8\ub77c \uc7a5\uba74 \uc18d \uc9e7\uc740 \uc601\uc5b4 \uc790\ub8cc\ub9cc \ub4e4\uc5b4\uac00\ub294\uc9c0 \uc810\uac80\ud574\uc8fc\uc138\uc694.", "\ub9c8\uc9c0\ub9c9 \ub9d0\ud558\uae30 \ub2e8\uacc4\uac00 \uc55e \ub2e8\uacc4\uc758 \ud310\ub2e8 \uae30\uc900\uc744 \uadf8\ub300\ub85c \uc0ac\uc6a9\ud574 \ud55c \ubb38\uc7a5 \uadfc\uac70 \uc124\uba85\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694."], "safetyNotes": ["\ud559\uc0dd\uc758 \uac1c\uc778 \ub2a5\ub825\uc774\ub098 \uc9c4\ub2e8\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ud45c\ud604\uc740 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\ud559\uad50 \uacf5\uac1c \uc815\ubcf4\ub294 \uc7a5\uba74 \ub9e5\ub77d\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uace0 \ud559\uc0dd \uac1c\uc778 \ud2b9\uc131 \ud310\ub2e8\uc5d0\ub294 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\uc774\ubbf8\uc9c0\uc5d0\ub294 \ubb38\uc81c \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8\ub97c \ub123\uc9c0 \uc54a\uace0 \ud544\uc694\ud55c \ubb38\uc7a5 \uc790\ub8cc\ub294 \uc9e7\uc740 \uc7a5\uba74 \ubb38\uad6c\ub85c\ub9cc \uc81c\ud55c\ud569\ub2c8\ub2e4.", "\uc601\uc5b4 \ubb38\uc7a5 \uc218\ub97c \uc801\uac8c \uc720\uc9c0\ud574 \uc77d\uae30 \ubd80\ub2f4\uc744 \ub0ae\ucda5\ub2c8\ub2e4."]}, "caseFile": {"profile": {"id": "student_learning_fraction", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_fraction", "displayName": "\uc774\ubbfc\uc900", "grade": "middle_2", "schoolCode": "8811058", "studentType": "learning_focus", "primaryNeed": "\uad6d\uc5b4 \uc77d\uae30 \uc790\ub8cc\uc758 \uc9e7\uc740 \uc815\ubcf4 \ubb38\uc7a5\uc5d0\uc11c \ud655\uc778 \uac00\ub2a5\ud55c \