INSERT INTO memory_cards VALUES('memory_clock_active','student_learning_clock','case_learning_clock',1,'["time_reading_sequence", "instruction_start_burden"]','{"summary": "\uadf8\ub9bc \ub2e8\uc11c\uc5d0\ub294 \ube60\ub974\uac8c \ubc18\uc751\ud558\uc9c0\ub9cc \uae34 \ubb38\uc7a5 \uc9c0\uc2dc\uc5d0\uc11c \uccab \ud589\ub3d9 \uc2dc\uc791\uc774 \ub2a6\uc5b4\uc9d0"}','쉬운 첫 문항을 성공하면 이후 선택 반응이 안정됩니다.','["scenario_image", "two_choice", "short_audio"]','["clock_hour_hand", "reading_order"]','home_short_practice_possible','["\uae34 \uc9c0\uc2dc\ubb38\uc744 \uba3c\uc800 \uc81c\uc2dc\ud558\uc9c0 \uc54a\uae30", "\uc9e7\uc740 \ubc14\ub298 \ucc3e\uae30 \uc131\uacf5 \ud6c4 \uae34 \ubc14\ub298\ub85c \ud655\uc7a5"]','2026-05-02T00:00:00.000Z','active');
INSERT INTO memory_cards VALUES('memory_fraction_active','student_learning_fraction','case_learning_fraction',1,'["fact_opinion_confusion", "evidence_explanation_burden"]','{"summary": "\uc2dc\uac01 \uc790\ub8cc\uc640 \uae30\uc900 \uce74\ub4dc\uc5d0\ub294 \uc798 \ubc18\uc751\ud558\uc9c0\ub9cc \ud310\ub2e8 \uadfc\uac70\ub97c \ub9d0\ud558\ub294 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc9e7\uc740 \ub3c4\uc6c0\ub9d0\uc774 \ud544\uc694\ud568"}','첫 판단을 맞히면 이후 이유 말하기까지 참여가 안정됩니다.','["scenario_image", "criteria_cards", "short_explain_back"]','["fact_opinion_boundary", "reason_sentence"]','normal','["\ubb38\uc7a5\uc744 \uae38\uac8c \ud574\uc124\ud558\uae30\ubcf4\ub2e4 \uba3c\uc800 \ud655\uc778 \uac00\ub2a5\ud55c \ub2e8\uc11c\ub97c \ucc3e\uae30", "\ub2f5\ub9cc \uace0\ub974\uc9c0 \uc54a\uace0 \uc774\uc720\ub97c \ud55c \ubb38\uc7a5\uc73c\ub85c \uc774\uc5b4 \ub9d0\ud558\uae30"]','2026-05-02T00:00:00.000Z','active');
