INSERT INTO content_assets VALUES('asset_content_bus_to_center_001_hero','content_bus_to_center_001',NULL,'hero','image','openai','gpt-image-2','{"prompt": "\ubc1d\uc740 \ub0ae, \ud55c\uad6d \ucd08\ub4f1\ud559\uc0dd \ub610\ub798 \uc544\uc774\uac00 \ucc45\uac00\ubc29\uc744 \uba54\uace0 \uae54\ub054\ud55c \ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310 \uc55e\uc5d0 \uc11c \uc788\ub294 \uc7a5\uba74. \ub4a4\ucabd \ub3c4\ub85c\uc5d0\uc11c\ub294 \ub178\ub780\uc0c9\uacfc \ucd08\ub85d\uc0c9\uc774 \uc11e\uc778 \ub2e8\uc21c\ud55c \ub514\uc790\uc778\uc758 \ub178\uc120 \ubc84\uc2a4 \ud55c \ub300\uac00 \ucc9c\ucc9c\ud788 \ub2e4\uac00\uc624\uace0 \uc788\ub2e4. \ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310\uc5d0\ub294 \uad75\uc740 \uc120\uc73c\ub85c \uadf8\ub9b0 \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \ud06c\uac8c \uc788\uace0, \uc815\ub958\uc7a5 \uc774\ub984\uc774\ub098 \ubc88\ud638 \ub4f1 \uae00\uc790\ub294 \uc804\ud600 \uc5c6\ub2e4. \uba40\ub9ac\uc5d0\ub294 \uad50\uc721\uc13c\ud130 \uac74\ubb3c\ucc98\ub7fc \ubcf4\uc774\ub294 \ub2e8\uc21c\ud55c \uac74\ubb3c\uc774 \uc791\uac8c \ubcf4\uc774\uc9c0\ub9cc \uac04\ud310 \uae00\uc528\ub294 \uc5c6\uc774 \ud615\ud0dc\ub9cc \ud45c\ud604\ub41c\ub2e4. \uc804\ubc18\uc801\uc778 \ubd84\uc704\uae30\ub294 \uc548\uc804\ud558\uace0 \ucc28\ubd84\ud558\uba70, \ud559\uc2b5 \ud65c\ub3d9\uc73c\ub85c \u2018\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \ud558\ub8e8\u2019\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc88b\uc740, \uae68\ub057\ud55c \uc0c9\uac10\uc758 \uc77c\ub7ec\uc2a4\ud2b8 \uc2a4\ud0c0\uc77c. \uc7a5\uba74 \uc548\uc5d0\ub294 \uc5b4\ub5a4 \ubb38\uc81c \ubb38\uc7a5\uc774\ub098 \uc815\ub2f5, \uc120\ud0dd\uc9c0, \ud78c\ud2b8 \uac19\uc740 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "hero", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_hero.png','/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_hero.png','passed','approved');
