INSERT INTO content_assets VALUES('asset_content_bus_to_center_001_stage_1','content_bus_to_center_001','stage_bus_to_center_001_1','stage_1','image','openai','gpt-image-2','{"prompt": "\ubc1d\uc740 \ub0ae, \ubc84\uc2a4 \uc815\ub958\uc7a5 \uc758\uc790\uc640 \uac04\ub2e8\ud55c \uc9c0\ubd95\uc774 \uc788\ub294 \uc791\uc740 \uc815\ub958\uc7a5 \uc7a5\uba74. \uc815\ub958\uc7a5 \uc606\uc5d0\ub294 \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \ud06c\uac8c \uadf8\ub824\uc9c4 \ud45c\uc9c0\ud310\uc774 \uc788\uace0, \uae00\uc790\ub294 \uc804\ud600 \uc5c6\ub2e4. \ucd08\ub4f1\ud559\uc0dd \ub610\ub798 \uc544\uc774\uac00 \uac00\ubc29\uc744 \uba54\uace0 \uc815\ub958\uc7a5 \uc55e\uc5d0 \uac00\uc9c0\ub7f0\ud788 \uc11c \uc788\uc73c\uba70, \uc606\uc5d0\ub294 \uc6c3\ub294 \ud45c\uc815\uc758 \uc791\uc740 \uac15\uc544\uc9c0 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ud568\uaed8 \uc11c \uc788\ub2e4. \uba40\ub9ac \ub3c4\ub85c\uc5d0\uc11c \ubc84\uc2a4 \ud55c \ub300\uc758 \uc55e\ubaa8\uc2b5\uc774 \ucc9c\ucc9c\ud788 \ub2e4\uac00\uc624\uace0 \uc788\ub2e4. \ud558\ub298\uacfc \uae38\uc740 \ub2e8\uc21c\ud55c \uc0c9\uac10\uc73c\ub85c \ud45c\ud604\ub418\uace0, \uc804\uccb4 \ubd84\uc704\uae30\ub294 \uc548\uc804\ud558\uace0 \ucc28\ubd84\ud558\ub2e4. \uc815\ub958\uc7a5 \uc774\ub984\uc774\ub098 \uc2dc\uac04\ud45c, \uad11\uace0 \ubb38\uad6c \uac19\uc740 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4. \ubb38\uc81c \ubb38\uc7a5, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8 \uac19\uc740 \ud14d\uc2a4\ud2b8\ub294 \uc804\ud600 \uc5c6\uc774 \uc7a5\uba74\ub9cc \ubcf4\uc774\ub3c4\ub85d \ud55c\ub2e4.", "visualRole": "stage_1", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_stage_1.png','/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_stage_1.png','passed','approved');
INSERT INTO content_assets VALUES('asset_content_bus_to_center_001_stage_1_audio','content_bus_to_center_001','stage_bus_to_center_001_1','stage_1','audio','elevenlabs','eleven_multilingual_v2','null','버스 정류장에서 버스를 기다리는 그림을 보면서, 오늘 함께 연습할 일을 살짝 떠올려 봅시다.','/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_stage_1_audio.mp3','/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_stage_1_audio.mp3','passed','approved');
INSERT INTO content_assets VALUES('asset_content_bus_to_center_001_stage_2','content_bus_to_center_001','stage_bus_to_center_001_2','stage_2','image','openai','gpt-image-2','{"prompt": "\ud654\uba74\uc774 \uc67c\ucabd\uacfc \uc624\ub978\ucabd \ub450 \ubd80\ubd84\uc73c\ub85c \ub098\ub25c \uc77c\ub7ec\uc2a4\ud2b8. \uc67c\ucabd\uc5d0\ub294 \ubc84\uc2a4 \uc815\ub958\uc7a5 \uc7a5\uba74: \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \uadf8\ub824\uc9c4 \ud45c\uc9c0\ud310, \uc758\uc790, \ub3c4\ub85c, \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uba70 \uc11c \uc788\ub294 \ucd08\ub4f1\ud559\uc0dd \uc544\uc774\uc640 \uc791\uc740 \uac15\uc544\uc9c0 \ub9c8\uc2a4\ucf54\ud2b8. \uc624\ub978\ucabd\uc5d0\ub294 \uc9d1 \uac70\uc2e4\uc774\ub098 \uad50\uc2e4 \uac19\uc740 \uc2e4\ub0b4 \uc7a5\uba74: \ucc45\uc0c1\uacfc \uc758\uc790, \uc120\ubc18\uc774 \uc788\ub294 \uc2e4\ub0b4 \ubc30\uacbd \uc18d\uc5d0 \uac19\uc740 \uc544\uc774\uc640 \uac19\uc740 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ud568\uaed8 \uc788\ub2e4. \ub450 \uc7a5\uba74 \ubaa8\ub450 \uae00\uc790\ub294 \uc804\ud600 \uc5c6\uace0, \ubc30\uacbd \ubd84\uc704\uae30\uc640 \ubb3c\uac74\ub4e4\uc774 \ub2ec\ub77c\uc11c \u2018\ubc16\uc758 \ubc84\uc2a4 \uc815\ub958\uc7a5\u2019\uacfc \u2018\uc2e4\ub0b4\u2019\uac00 \ud655\uc2e4\ud788 \uad6c\ubd84\ub418\ub3c4\ub85d \ud45c\ud604\ud55c\ub2e4. \uc5b4\ub5a4 \ubb38\uc81c \ubb38\uc7a5\uc774\ub098 \uc120\ud0dd\uc9c0, \uc7a5\uc18c \uc774\ub984 \uae00\uc790, \ub9d0\ud48d\uc120 \ud14d\uc2a4\ud2b8\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_2", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_stage_2.png','/generated/assets/students/student_learning_clock/content_bus_to_center_001/asset_content_bus_to_center_001_stage_2.png','passed','approved');
