INSERT INTO content_assets VALUES('asset_content_generated_001_hero','content_generated_001',NULL,'hero','image','openai','gpt-image-2','{"prompt": "Premium Korean edtech illustration of a calm, bright public library interior. Show wide aisles, neat bookshelves, warm natural light, and a librarian desk in the distance. A blue-covered animal picture book is visible naturally on one shelf, with only a simple animal icon on the cover and no readable title. Include one elementary-age Korean student entering or looking around comfortably, not stressed. Composition should feel like a welcoming overview before the mission starts, with clear subject separation and generous empty space for frontend UI overlay. Warm but not childish, polished digital illustration, soft realistic proportions, varied library colors, no decorative gradient blobs, no stock-photo feeling.", "visualRole": "hero", "scene": "\uc870\uc6a9\ud55c \ub3c4\uc11c\uad00 \uc804\uccb4 \uc0c1\ud669 \uc608\uace0", "style": "\ub530\ub73b\ud55c \ud55c\uad6d \uad50\uc721\uc6a9 \ub514\uc9c0\ud138 \uc77c\ub7ec\uc2a4\ud2b8, \ubd80\ub4dc\ub7ec\uc6b4 \uc0c9\uac10, \uba85\ud655\ud55c \uad6c\ub3c4", "avoid": ["\uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790", "\ud654\uba74\uc6a9 \ub2e8\ucd94", "\uc815\ub2f5 \ud45c\uc2dc", "\uc124\uba85 \ubb38\uad6c", "\ubcf5\uc7a1\ud55c \uae30\ud638", "\ud45c\uc9c0 \uc81c\ubaa9"], "textRenderingPolicy": "scene_only_no_problem_text", "promptVersion": "image_brief_v1", "negativePromptRules": ["no problem statements", "no answer choices", "no hints", "no long Korean text", "no watermark", "no readable book titles", "no UI panels or buttons", "no speech bubbles", "no worksheet-like layout"], "ocrRequired": false, "qaChecklist": ["scene matches stage purpose", "no UI text embedded", "no confusing extra answer objects", "student-safe tone", "blue animal book is visible but not presented as a UI answer"]}',NULL,'/generated/assets/students/student_life_bus/content_generated_001/asset_content_genera