INSERT INTO content_assets VALUES('asset_content_generated_001_stage_2_audio','content_generated_001','stage_content_generated_001_2','stage_2','audio','elevenlabs','eleven_multilingual_v2','null','이번에는 책의 단서 하나에 집중해요. 파란 표지를 찾아보면 좋아요.','/generated/assets/students/student_life_bus/content_generated_001/asset_content_generated_001_stage_2_audio.mp3','/generated/assets/students/student_life_bus/content_generated_001/asset_content_generated_001_stage_2_audio.mp3','passed','approved');
