INSERT INTO content_assets VALUES('asset_content_learning_environment_fact_opinion_stage_1','content_learning_environment_fact_opinion','stage_learning_environment_fact_opinion_1','stage_1','image','openai','gpt-image-2','{"prompt": "Premium Korean edtech illustration for a middle school Korean reading lesson. Show a bright Korean middle school hallway bulletin board with environmental campaign posters. The main posters must contain clearly readable Korean source text, rendered large and clean inside the posters: \"\uc624\ub298 \uc6b0\ub9ac \ubc18\uc740 \uc885\uc774\ucef5 20\uac1c\ub97c \ubaa8\uc558\uc5b4\uc694.\" and \"\ud140\ube14\ub7ec\ub97c \uc4f0\uba74 \ub354 \uba4b\uc838\uc694.\" A middle school student points at the poster while comparing which sentence can be checked and which sentence contains a thought. Include recycling bins, paper cups, and a tumbler as real scene objects. Mature warm illustration style, clear composition, no worksheet UI, no answer labels, no category words, no matching cards, no buttons, no speech bubbles, no hints, no correct answer indicators.", "visualRole": "stage_1", "scene": "\ud658\uacbd \ud3ec\uc2a4\ud130\uc5d0\uc11c \ud655\uc778 \uac00\ub2a5\ud55c \uc815\ubcf4\uc640 \uc0dd\uac01 \ud45c\ud604\uc744 \uad6c\ubd84\ud558\uae30 \uc804\uc758 \uad00\ucc30 \uc7a5\uba74", "style": "\ucc28\ubd84\ud55c \ud55c\uad6d \uc911\ud559\uad50 \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8", "avoid": "\uc77d\uc744 \uc218 \uc788\ub294 \ubb38\uc7a5, \uc22b\uc790, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \uc124\uba85 \uadf8\ub798\ud53d", "textRenderingPolicy": "short_scene_text_allowed_no_problem_ui", "promptVersion": "image_brief_v1", "negativePromptRules": ["no answer choices", "no answer labels", "no category labels such as \uc0ac\uc2e4 or \uc758\uacac", "no worksheet cards", "no UI panels", "no buttons", "no speech bubbles", "no hints", "no extra long text", "no watermark"], "ocrRequired": true, "qaChecklist": ["scene matches stage purpose", "no UI text embedded", "no confusing extra answer objects", "student-safe tone", "concept introduction feels observational", "fact versus opinion theme is suggested visually without text"], "sceneTextLines": ["\uc624\ub298 \uc6b0\ub9ac \ubc18\uc740 \uc885\uc774\ucef5 20\uac1c\ub97c \ubaa8\uc558\uc5b4\uc694.", "\ud140\ube14\ub7ec\ub97c \uc4f0\uba74 \ub354 \uba4b\uc838\uc694."]}',NULL,'/generated/assets/students/student_learning_fraction/content_learning_environment_fact_opinion/asset_content_learning_environment_fact_opinion_stage_1.png','/generated/assets/students/student_learning_fraction/content_learning_environment_fact_opinion/asset_content_learning_environment_fact_opinion_stage_1.png','passed','approved');
