INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_hero','content_learning_fraction_store_discount',NULL,'hero','image','openai','gpt-image-2','{"prompt": "\ud55c\uad6d \uc911\ud559\uad50 \uc548\uc5d0 \uc788\ub294 \ubc1d\uc740 \ubd84\uc704\uae30\uc758 \ud559\uad50 \ub9e4\uc810 \ub0b4\ubd80 \uc804\uacbd. \ub2e4\uc591\ud55c \uacfc\uc790\uc640 \uc74c\ub8cc\uac00 \uc9c4\uc5f4\ub41c \uc9c4\uc5f4\ub300\uc640 \ub0c9\uc7a5\uace0\uac00 \ubcf4\uc774\uace0, \uc9c4\uc5f4\ub300 \uc55e\uc5d0\ub294 \uc911\ud559\uc0dd \ub0a8\ud559\uc0dd \ud55c \uba85\uc774 \uac04\uc2dd\uc744 \uace0\ub974\uba70 \uac00\uaca9\ud45c\ub97c \uc720\uc2ec\ud788 \ubc14\ub77c\ubcf4\uace0 \uc788\ub2e4. \uba87\uba87 \uac00\uaca9\ud45c\uc5d0\ub294 \ub178\ub780\uc0c9\uc774\ub098 \ube68\uac04\uc0c9\uc758 \uc791\uc740 \u2018\ud560\uc778\u2019 \uc2a4\ud2f0\ucee4\ub098 \uc138\uc77c \uc544\uc774\ucf58\uc774 \ubd99\uc5b4 \uc788\uc9c0\ub9cc, \uad6c\uccb4\uc801\uc778 \uc22b\uc790\ub098 \ubd84\uc218, \ubb38\uc81c \ubb38\uc7a5\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad50\ubcf5\uc774\ub098 \ud6c4\ub4dc\ud2f0\ub97c \uc785\uc740 \ud559\uc0dd\uc774 \uace0\ubbfc\ud558\ub294 \ud45c\uc815\uc73c\ub85c \uac00\uaca9\ud45c\ub97c \ubc14\ub77c\ubcf4\ub294 \uc7a5\uba74. \uc804\ubc18\uc801\uc778 \uc2a4\ud0c0\uc77c\uc740 \uc120\uba85\ud55c \uc0c9\uac10\uc758 \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8, \ub9cc\ud654\uac00 \uc544\ub2c8\ub77c \uc0ac\uc2e4\uc801\uc778 \ub290\ub08c. \uadf8\ub9bc \uc548\uc5d0\ub294 \ubb38\uc81c \ubb38\uc7a5, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8, \uc218\uc2dd \uac19\uc740 \uae34 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "hero", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/students/student_learning_fraction/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_hero.png','/generated/assets/students/student_learning_fraction/content_learning_fraction_store_discount/asset_cont