INSERT INTO realtime_practice_sessions VALUES('rt_session_e5fcfe4e-e93e-4366-8857-7b0dfd32977e','attempt_bf20b0c0-117d-40c5-bccb-a4491261e039','content_learning_environment_fact_opinion','stage_learning_environment_fact_opinion_4','student_learning_fraction','openai','gpt-realtime-1.5','created','{"id": "rt_spec_learning_environment_fact_opinion", "stageId": "stage_learning_environment_fact_opinion_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_learning_environment_fact_opinion_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ud3ec\uc2a4\ud130 \ubb38\uad6c \ud310\ub2e8 \uc774\uc720 \ub9d0\ud558\uae30", "situationText": "\uce5c\uad6c\uac00 \ud658\uacbd \ucea0\ud398\uc778 \ud3ec\uc2a4\ud130 \ubb38\uad6c\ub97c \ubcf4\uace0 \uc5b4\ub5a4 \ub9d0\uc774 \uc0ac\uc2e4\uc774\uace0 \uc5b4\ub5a4 \ub9d0\uc774 \uc758\uacac\uc778\uc9c0 \uad81\uae08\ud574\ud558\uace0 \uc788\uc5b4\uc694.", "aiRole": "\ud3ec\uc2a4\ud130\ub97c \ud568\uaed8 \ubcf4\ub294 \uce5c\uad6c", "openingLine": "\uc774 \ub450 \ubb38\uad6c\ub97c \uac19\uc774 \ubd10 \uc904\ub798? \u201c\uc624\ub298 \uc6b0\ub9ac \ubc18\uc740 \uc885\uc774\ucef5 20\uac1c\ub97c \ubaa8\uc558\uc5b4\uc694.\u201d\uc640 \u201c\ud140\ube14\ub7ec\ub97c \uc4f0\uba74 \ub354 \uba4b\uc838\uc694.\u201d \uc911\uc5d0\uc11c \uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \ub098\ub204\uace0, \uc774\uc720\ub3c4 \uc9e7\uac8c \ub9d0\ud574\uc918.", "studentGoal": "\ud3ec\uc2a4\ud130 \ubb38\uad6c \ud55c\ub450 \uac1c\ub97c \ubcf4\uace0 \ud655\uc778\ud560 \uc218 \uc788\ub294 \ub0b4\uc6a9\uc778\uc9c0, \uc0dd\uac01\uc774\ub098 \uad8c\uc720\uac00 \ub2f4\uae34 \ub9d0\uc778\uc9c0 \uc790\uc2e0\uc758 \ub9d0\ub85c \uc9e7\uac8c \uc124\uba85\ud574 \ubcf4\uae30", "rubric": [{"id": "meaningful_attempt", "label": "\uc790\uc2e0\uc774 \uc0dd\uac01\ud55c \ud310\ub2e8\uc744 \ud55c \ubc88 \uc774\uc0c1 \ub9d0\ud574 \ubcf8\ub2e4.", "required": true}, {"id": "core_reason", "label": "\ud655\uc778 \uac00\ub2a5\uc131\uc774\ub098 \uc0dd\uac01 \ud45c\ud604\uc744 \ub4e4\uc5b4 \uc774\uc720\ub97c \ub9d0\ud574 \ubcf8\ub2e4.", "required": true}, {"id": "separate_fact_opinion", "label": "\uc0ac\uc2e4\uacfc \uc758\uacac \uc911 \ud558\ub098 \uc774\uc0c1\uc744 \uad6c\ubd84\ud574 \ubcf8\ub2e4.", "required": false}, {"id": "use_short_sentence", "label": "\uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ucc28\ubd84\ud788 \uc124\uba85\ud574 \ubcf8\ub2e4.", "required": false}], "allowedFeedback": ["\uc88b\uc544\uc694. \uc5b4\ub5a4 \ucabd\uc778\uc9c0 \uba3c\uc800 \ub9d0\ud574 \uc900 \uc810\uc774 \uc88b\uc544\uc694. \uc774\ubc88\uc5d0\ub294 \uc65c \uadf8\ub807\uac8c \uc0dd\uac01\ud588\ub294\uc9c0 \ud55c \ubb38\uc7a5\ub9cc \ub367\ubd99\uc5ec \ubcfc\uae4c\uc694?", "\uad1c\ucc2e\uc544\uc694. \uc9e7\uac8c \ub9d0\ud574\ub3c4 \ucda9\ubd84\ud574\uc694. \uc774 \ubb38\uad6c\uac00 \uc9c1\uc811 \ud655\uc778 \uac00\ub2a5\ud55c\uc9c0\ubd80\ud130 \ub9d0\ud574 \ubcfc\uae4c\uc694?", "\uc798 \uc2dc\uc791\ud588\uc5b4\uc694. \uc774\uc81c \uc0dd\uac01\uc774\ub098 \ub290\ub08c\uc774 \ub4e4\uc5b4 \uc788\ub294 \ub9d0\uc778\uc9c0 \ud55c \ubc88 \ub354 \uc0b4\ud3b4\ubcfc\uae4c\uc694?", "\uc88b\uc544\uc694. \uc9c0\uae08 \ub9d0\ud55c \uc774\uc720\ub97c \u2018\ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc11c\u2019 \ub610\ub294 \u2018\uc0dd\uac01\uc774 \ub2f4\uaca8 \uc788\uc5b4\uc11c\u2019\ub85c \uc774\uc5b4 \ub9d0\ud574 \ubcfc\uae4c\uc694?"], "forbidden": ["\ud559\uc0dd\uc5d0\uac8c \uc9c4\ub2e8\uc774\ub098 \ub2a5\ub825\uacfc \uad00\ub828\ub41c \ub9d0\uc744 \ud558\uc9c0 \uc54a\uae30", "\ub2f5\uc774 \uc9e7\ub2e4\uace0 \ud2c0\ub838\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0 \uc54a\uae30", "\uac1c\uc778\uc815\ubcf4\ub97c \ubb3b\uac70\ub098 \ub9d0\ud558\uc9c0 \uc54a\uae30", "\uc0c8\ub85c\uc6b4 \uc5b4\ub824\uc6b4 \ubb38\ubc95 \uc6a9\uc5b4\ub97c \ucd94\uac00\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 150, "postPracticeReflection": ["\ud655\uc778\ud560 \uc218 \uc788\ub294 \ub9d0\uc740 \ucc3e\uae30 \uc26c\uc6e0\uc5b4\uc694.", "\uc0dd\uac01\uc774 \ub2f4\uae34 \ub9d0\uc740 \uc870\uae08 \ub354 \uc5f0\uc2b5\ud558\uace0 \uc2f6\uc5b4\uc694.", "\uc774\uc720\ub97c \uc9e7\uac8c \ub9d0\ud574 \ubcf4\ub2c8 \ub3c4\uc6c0\uc774 \ub410\uc5b4\uc694."]}',NULL,NULL,0,0,'null',NULL);
